Dargah.service('FieldService', ['$http', '$timeout', 'Upload', '$parse', function (Upload) {
    return function (fields, tableID, $scope) {
        var isvalid = true;
        var forms = fields;
        var getdata = function () {
            var list = [];
            angular.forEach(forms, function (i) {
                var obj = {};
                obj["Key"] = i.ID;
                var val = i.Value;
                if (val && i.DataType === "multiselect") {
                    if (Array.isArray(val)) {
                        i.Value = val.join();
                    } else {
                        i.Value = val;
                    }
                }
                else if (i.DataType === "date" && val) {
                    if (cultureInfo === "fa-IR") {
                        i.Value = persianDateConverting(val);
                    }
                    else {
                        i.Value = val;
                    }
                }
                else if (i.DataType === "file") {
                    i.Value = $('#myFile' + i.ID).val();
                }
                obj["Value"] = i.DataType === 'formol' ? i.formol : i.Value;
                list.push(obj);
            });
            return list;
        };
        var checkvalid = function () {
            angular.forEach(fields, function (i) {
                if (i.Required === "Y") {
                    if (!i.Value && i.DataType !== "file")
                        isvalid = false;
                    else if (i.DataType === "file") {
                        let fileState = validateFile(('myFile' + i.ID), (i.Required === "Y"));
                        if (isvalid === true)
                            isvalid = fileState.isValid;
                    }
                }
            });
            return isvalid;
        };
        var UploadFile = function (tableID, i, formfields) {
            i.Upload = true;
            var fileUpload = $('#myFile' + i.ID).get(0);
            var files = fileUpload.files[0];
            if (files) {
                Upload.upload({
                    method: 'POST', url: '/base/formfields/PostField?id=' + tableID + '&&fieldID=' + i.ID,
                    headers: {
                        "X-CSRF-Token": defaultForgery,
                    },
                    file: files,
                }).progress(function (evt) {
                    i.progress = Math.min(100, parseInt(100.0 * evt.loaded / evt.total));
                }).then(function successCallback(res) {
                    if (!res.data.success) {
                        notifyShow('فرمت فایل وارد شده نامعتبر می باشد', 0);
                        return;
                    } else {
                        notifyShow('آپلود فایل با موفقیت انجام شد', 2);
                    }
                }, function errorCallback(data) { });
            } else {
                notifyShow('لطفا فایل را وارد نمایید', 0);
            }
            return isvalid;
        };
        var TagBoxes = ($parse) => {
            $scope.formfieldsDataSourceTagBoxes = fields.filter(x => x.DataType == "multiselect");
            $scope.formfieldsDataSourceTagBoxes.map((item) => {
                var tagBoxFormField = $parse("tagBoxFormField_" + item.ID)
                if (item.Value && !Array.isArray(item.Value)) {
                    item.Value = item.Value.split(",");
                } else if (!(item.Value)) {
                    item.Value = null;
                }
                item.customTemplateFormField = {
                    dataSource: item.DropdownItems,
                    displayExpr: 'Value',
                    valueExpr: 'Key',
                    searchEnabled: true,
                    placeholder: item.Placeholder,
                };
            });
            return $scope.formfieldsDataSourceTagBoxes;
        }
        return {
            data: getdata,
            valid: checkvalid,
            UploadFile: UploadFile,
            TagBoxes: TagBoxes,
        };
    };
}]);
Dargah.service('dynamicFieldGridServices', [function () {

    let dataItems = this;
    function newDownBtn(id, idImg) {
        let h = document.createElement("div"), btnDown = document.createElement("a");
        btnDown.classList = "zmdi zmdi-download";
        h.appendChild(btnDown);
        h.style = "width: 100%;position: relative;"
        btnDown.style = "font-size: 34px;color: gray;text-align: center;width: 100%;display: block;";
        h.onclick = () => {
            window.open(`/Additional/downloadfile?id=${id}&fieldid=${idImg}`);
        }
        return h;
    }
    function parseWidth(i) {
        if (i < 5)
            return (i * 20)
        else if (i < 10)
            return (i * 15)
        else if (i < 50)
            return (i * 12)
        else
            return (i * 6)
    }
    this.addDynamicFields = function (allCols, dynamicCols) {
        for (let sCol of dynamicCols) {
            let newCol = {
                caption: sCol.Name,
                dataField: "staticSource_" + sCol.ID,
                allowFiltering: false,
                allowColumnReordering: false,
                allowSorting: false,
                width: "100px",
            }
            if (sCol.DataType === "date") {
                try {
                    newCol.dataType = "string";
                    newCol.cellTemplate = function (cellElement, cellInfo) {
                        if (cellInfo.text !== "Invalid date" && cellInfo.text.length !== 0) {
                            if (cultureInfo === "fa-IR") {
                                try {
                                    cellElement.append(moment.from(cellInfo.text, 'en', 'MM/DD/YYYY').locale('fa').format('YYYY/MM/DD'));
                                } catch (e) { return cellElement.text(cellInfo.text) }
                            } else {
                                cellElement.append(moment.from(cellInfo.text, 'en', 'MM/DD/YYYY').locale('en').format('MM/DD/YYYY'));
                            }
                        }
                    }
                } catch (err) { console.log(err) }
            }
            else if (sCol.DataType === "multiselect") {
                newCol.DropdownItems = sCol.DropdownItems;
                newCol.lookup = { dataSource: newCol.DropdownItems, valueExpr: 'Key', displayExpr: 'Value' };
                newCol.cellTemplate = (element, info) => {
                    var multiselectColumnValues = "";
                    if (info.value) {
                        info.value = info.value.split(",");
                        info.value.map((item, index) => {
                            if (sCol.DropdownItems.find(x => x.Key == item)) {
                                multiselectColumnValues += sCol.DropdownItems.find(x => x.Key == item).Value + " ,"
                            }
                        });
                        element.text(multiselectColumnValues)
                    };
                };
            }
            else if (sCol.DataType === "file") {
                newCol.cellTemplate = function (cellElement, cellInfo) {
                    if (cellInfo.value && cellInfo.value.length !== 0) {
                        let idImg = cellInfo.column.name;
                        idImg = idImg.substring(13, idImg.length);
                        let id = cellInfo.row.data.ID._value;
                        cellElement.append(newDownBtn(id, idImg));
                    }
                }
            }
            else if (sCol.DataType === "number" || sCol.DataType === "string") {
                newCol.dataType = sCol.DataType;
            }
            else if (sCol.DataType === "link") {
                newCol.dataType = "string";
                newCol.cellTemplate = function (cellElement, cellInfo) {
                    if (cellInfo.value)
                        cellElement.append(`<a href="${cellInfo.value}">${cellInfo.value}</a>`);
                }
            }
            else if (sCol.DataType === "dropdowm") {
                newCol.dataType = "string";
                newCol.cellTemplate = function (cellElement, cellInfo) {
                    if (cellInfo.value && cellInfo.value !== null && cellInfo.value !== undefined)
                        if (sCol.DropdownItems.find(x => x.Key == cellInfo.value) !== null && sCol.DropdownItems.find(x => x.Key == cellInfo.value) !== undefined)
                            cellElement.append(sCol.DropdownItems.find(x => x.Key == cellInfo.value).Value);
                }
            }
            else {
                newCol.dataType = sCol.DataType;
            }
            allCols.push(newCol)
        }
        return allCols;
    }
    this.addStatciFields = function (allCols, staticCols) {

        return dataItems.addDynamicFields(allCols, staticCols);
    }
    this.newDataSource = function (url, onLoaded) {
        return new DevExpress.data.ODataStore({
            url: url,
            key: 'ID',
            version: 4,
            onLoaded: function (allData) {
                for (let data of allData) {
                    if (data.JsonFields == null)
                        continue;
                    let jsonData = JSON.parse(data.JsonFields);
                    for (let item of jsonData) {
                        data["staticSource_" + item.Key] = item.Value;
                    }
                }
                if (onLoaded)
                    onLoaded(allData);
            }
        })
    }
    return this;
}]);
Dargah.service('archiveViewerManagerService', ['$http', '$timeout', 'toaster', function ($http, $timeout, toaster) {
    return function (params, scope) {
        var parentID = scope.parentID;
        var FileIndex = null;
        var FolderIndex = null;
        scope.FileIndex = 50;
        scope.FolderIndex = 50;
        scope.setpage = 1;
        var loading = scope.loading;
        var load = function () {

            scope.uploadProgress = 0;
            scope.FolderCount = 0;
            scope.FileCount = 0;
            scope.loading = true;
            var Isload = true;
            var id = $timeout(frame, 50);
            var width = 1;
            function frame() {
                if (Isload) {
                    var elem = document.getElementById("progress-bar");
                    if (width >= 100) {
                        scope.uploadProgress = 100;
                        scope.loading = false;
                    } else {
                        width++;
                        scope.uploadProgress = width;
                        if (elem !== null)
                            elem.style.width = width + '%';
                        $timeout(frame, 50);
                    }
                }
                else {
                    scope.uploadProgress = 100;
                    scope.loading = false;
                }
            }
            $http.post('/archivemanager/getStructure?section=' + params.section + '&objectID=' + params.objectID + '&id=' + (parentID !== '' ? parentID : '') + '&Count=' + FileIndex + '&FolderCount=' + FolderIndex)
                .then(function successCallback(res) {
                    Isload = false;
                    scope.FileList = res.data.data.FileList;
                    scope.FolderList = res.data.data.FolderList;
                    scope.FileCount = res.data.data.FileCount;
                    scope.FolderCount = res.data.data.FolderCount;
                    if (res.data.Lenght > 0)
                        scope.Path = res.data.data.Path;
                }, function errorCallback(res) { });
            scope.FileIndex = 50;
            scope.FolderIndex = 50;
        };
        var itemClick = function (i, $event) {
            if ($event.ctrlKey) {
                i._checked = !i._checked;
            }
            else if ($event.shiftKey) {
                var firstSelectedFound = null;
                angular.forEach(scope.FolderList, function (j) {
                    if (firstSelectedFound === null && j._checked) firstSelectedFound = true;
                    if (firstSelectedFound) j._checked = true;
                    if (i === j) firstSelectedFound = false;
                });
                angular.forEach(scope.FileList, function (j) {
                    if (firstSelectedFound === null && j._checked) firstSelectedFound = true;
                    if (firstSelectedFound) j._checked = true;
                    if (i === j) firstSelectedFound = false;
                });
            }
            else {
                angular.forEach(scope.FolderList, function (j) {
                    j._checked = false;
                });
                angular.forEach(scope.FileList, function (j) {
                    j._checked = false;
                });
                i._checked = true;
            }
            if ($event.stopPropagation) $event.stopPropagation();
            if ($event.preventDefault) $event.preventDefault();
            $event.cancelBubble = true;
            $event.returnValue = false;
            scope.CurrentData = i;
        };
        var getloading = function () {

            return loading;
        };
        var itemDblClick = function (model) {

            scope.loading = true;
            if (model.Folder) {
                parentID = model.ID;
                scope.FileIndex = 50;
                scope.FolderIndex = 50;
                load();
            }
            else {
                scope.loading = false;
                window.open('/archivemanager/download/' + model.ID);
            }
        };
        var goUp = function () {

            scope.FileIndex = 50;
            $http.post('/archivemanager/GetParent?ID=' + parentID)
                .then(function successCallback(res) {
                    parentID = res.data.data;
                    load();
                });
        };
        var selectAll = function () {

            angular.forEach(scope.FolderList, (i) => i._checked = true);
            angular.forEach(scope.FileList, (i) => i._checked = true);
        };
        var selectNone = function () {

            angular.forEach(scope.FolderList, (i) => i._checked = false);
            angular.forEach(scope.FileList, (i) => i._checked = false);
        };
        var getPath = function () {

            return parentID;
        };

        return {
            load: load,
            itemClick: itemClick,
            itemDblClick: itemDblClick,
            goUp: goUp,
            selectAll: selectAll,
            selectNone: selectNone,
            getPath: getPath,
            getloading: getloading
        };
    };
}]);
