Dargah.directive('ngMobile', function () {
    return {
        restrict: 'A',
        link: function (scope, element, attrs) {
            function checkMobile() {
                let val = element.val();
                if (scope.defaultCountry == scope.selectedCountry && !val.startsWith("09")) {
                    element.val('09')
                }
                if (val && val !== null && val.length !== '' && val.startsWith("09")) {
                    val = val.replaceAll(/[آ-ی a-z A-Z .,،|!@#$%^&*()_+=-{}?><~``;'": ]+/g, '')
                    element.val(val)
                }
            };
            function addPreMobile() {
                let val = element.val();
                if (scope.defaultCountry == scope.selectedCountry && (val == null || val == "" || val.length == 0)) {
                    element.val('09')
                }
            };
            element.keydown(checkMobile);
            element.keyup(checkMobile);
            element.focus(addPreMobile);
        }
    };
});
