Dargah.directive('fileUploader', function () {
    return {
        restrict: 'E',
        transclude: true,
        scope: {
            allowedTypes: '=types',
            uploadData: '=data',
            required: '=required',
            additionaloption: '=additionaloption'
        },
        template:
            `<div class="input-group d-flex" ng-if="(uploadData.multiple===undefined||uploadData.multiple===false) && !(additionaloption.isDisabled)" ng-class="downloadUrl.length === 0 ? 'upload-sec-hidden' : 'upload-sec-show'">
                <input type="text" id="{{uploadData.name}}" name="{{uploadData.name}}" ng-model="fileData" style="display: none;"  ng-required= required==true />
                <div dx-file-uploader="uploader"></div>
                <div class="format-upload-dsc"></div>
                <div class="download-image-btn" ng-class="downloadUrl.length === 0 ? 'hidden-image-btn' : ''">
                    <div class="d-flex">
                        <a class="btn btn-primary" ng-if="!uploadMode"  ng-click="downFile();"><i class="fa fa-download"></i></a>
                        <a class="btn btn-danger mr-1" ng-click="clearFile();"><i class="fa fa-trash"></i></a>
                    </div>      
                </div>
            </div>
            <div class="input-group d-flex" ng-if="(uploadData.multiple === true) && !(additionaloption.isDisabled)"  ng-class="downloadUrl.length === 0 ? 'upload-sec-hidden' : 'upload-sec-show'">
                <input type="text" name="{{uploadData.name}}" ng-repeat="fd in fileData" ng-model="fd.data" style="display: none;"/>
                <div dx-file-uploader="uploader"></div>
                <div class="format-upload-dsc"></div>
                <div class="download-image-btn d-flex" ng-class="fileData.length > 0 ? '' : 'hidden-image-btn'">
                    <div class="d-flex">
                        <a class="btn btn-danger mr-1" ng-click="clearFile();"><i class="fa fa-trash"></i></a>
                    </div>      
                </div>
            </div>
             <div class="input-group d-flex" ng-if="additionaloption.isDisabled">
                <input type="text" class="form-control" placeholder="{{uploadData.label+(required?'*':'')}} {{downloadUrl.length === 0 ? '(فاقد فایل)':''}}" ng-disabled='true'>
                <div class="format-upload-dsc"></div>
                <div class="download-image-btn d-flex" ng-class="downloadUrl.length === 0 ? 'hidden-image-btn' : ''">
                    <a class="btn btn-primary" ng-if="!uploadMode" ng-click="downFile();"><i class="fa fa-download"></i></a>
                </div>
            </div>`,
        link($scope) {
            var instance;
            let title = () => {
                let placeholder = $scope.uploadData.placeholder == null ? " " : $scope.uploadData.placeholder;
                return $scope.downloadUrl && $scope.downloadUrl.length > 0 ? (IsRtl ? "ویرایش " : "edit") + placeholder : (IsRtl ? "آپلود " : "upload") + placeholder;
            }
            $scope.fileData = $scope.uploadData.value;
            $scope.clearFile = () => {
                instance.repaint();
                instance._$element.find(".dx-fileuploader-files-container").children().remove();
                if ($scope.uploadData.multiple) {
                    $scope.fileData = [];
                }
                else {
                    $scope.downloadUrl = "";
                    $scope.fileData = undefined;
                }

            }
            $scope.downFile = () => {
                const a = document.createElement('a');
                a.href = $scope.downloadUrl;
                a.download = $scope.fileData;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
            }
            if ($scope.uploadData.downloadUrl)
                $scope.downloadUrl = $scope.uploadData.downloadUrl;
            else $scope.downloadUrl = "";
            $scope.uploader =
            {
                onInitialized(e) {
                    instance = e.component;
                    e.element.parent().parent()[0].setAttribute("required", $scope.required);
                },
                selectionMode: "multiple",
                uploadMethod: "POST",  // Explicit method
                uploadUrl: $scope.uploadData.isNotLogedIn ? '/TempUpload/Upload2' : '/TempUpload/Upload',
                selectButtonText: title(),
                onFilesUploaded() {
                    let elts = instance._$element.find(".dx-fileuploader-files-container").children();
                    if (elts.length > 1)
                        elts.each(function (i, e) {
                            if ((elts.length - 1) !== i) {
                                e.remove();
                            }
                        })
                },
                labelText: (IsRtl ? "فایل خود را بکشید و در اینجا رها کنید" : "drag and drop your file"),
                uploadedMessage() {
                    if ($scope.uploadData.multiple)
                        return $scope.fileData.length + (IsRtl ? "اتمام بارگذاری" : "upload done");
                    else
                        return (IsRtl ? "اتمام بارگذاری" : "upload done");
                },
                onUploaded: function (e) {
                    let response = JSON.parse(e.request.response);
                    if ($scope.uploadData.multiple) {
                        $scope.fileData.push({ data: response.data.fileID });
                    }
                    else if (response.success) {
                        $scope.uploadMode = true;
                        $scope.downloadUrl = response.data.downloadUrl;
                        $scope.fileData = response.data.fileID;
                        e.component.option("selectButtonText", title());
                    }
                }
            };
            if ($scope.uploadData.multiple) {
                $scope.uploader.multiple = true;
                $scope.fileData = [];
            }
            if ($scope.allowedTypes) {
                $scope.uploader.accept = $scope.allowedTypes.map(x => x.Key).toString();
            }
        }
    }
});
Dargah.directive('emailValidate', function () {
    var EMAIL_REGEXP = /^[_a-z0-9]+(\.[_a-z0-9]+)*@[a-z0-9-]+(\.[a-z0-9-]+)*(\.[a-z]{2,4})$/;
    return {
        link: function (scope, elm) {
            elm.on("keyup", function () {
                var isMatchRegex = EMAIL_REGEXP.test(elm.val());
                if (isMatchRegex && elm.hasClass('warning') || elm.val() == '') {
                    elm.removeClass('warning');
                } else if (isMatchRegex == false && !elm.hasClass('warning')) {
                    elm.addClass('warning');
                }
            });
        }
    }
});
Dargah.directive('ngValidate', function () {
    return {
        restrict: 'A',
        scope: {
            ngBeforeSubmit: '&'
        },
        link: function (scope, element, attributes, formController) {
            var $elm = $(element).validator({ disable: false, custom: validatorCustomMethods });
            var $formContainer = $elm;
            $elm[0].Valid = true
            var count = 0;
            if (scope.ngBeforeSubmit && angular.isFunction(scope.ngBeforeSubmit)) {
                $elm.on('submit', function (e) {
                    $elm[0].Valid = true
                    $($formContainer).find("select, textarea, input").each(function () {
                        var input = $(this);
                        if (input.attr('required') !== undefined) {
                            if ((input.val() == undefined || input.val() === '? undefined:undefined ?' || input.val() == null || input.val() === " " || input.val() === "" || input.val() === '00000000-0000-0000-0000-000000000000' || input.val() === '?' || (Array.isArray(input.val())))) {
                                //console.log("add => " + input[0].attributes["name"].value + " , value => " + input.val() + " , length => " + input.parent('div').children().length)
                                if (input[0].options) {
                                    input.parent('div').parent('div').addClass('error has-error');
                                    input.parent('div').addClass('error has-error');
                                }
                                else {
                                    input.parent('div').addClass('error has-error');
                                }
                                $elm[0].Valid = false;
                            }
                            else {
                                //console.log("remove => " + input[0].attributes["name"].value + " , value => " + input.val() + " , length => " + input.parent('div').children().length)
                                if (input[0].options) {
                                    if (input.parent('div').children().length == 2) {
                                        var firstInputValue = input.parent('div').children()[0].value;
                                        var secondInputValue = input.parent('div').children()[1].value;
                                        var firstInputHasValue = !(firstInputValue == undefined ||
                                            firstInputValue === '? undefined:undefined ?' ||
                                            firstInputValue == null ||
                                            firstInputValue === " " ||
                                            firstInputValue === "" ||
                                            firstInputValue === '00000000-0000-0000-0000-000000000000' ||
                                            firstInputValue === '?' ||
                                            (Array.isArray(firstInputValue)));
                                        var secondInputHasValue = !(secondInputValue == undefined ||
                                            secondInputValue === '? undefined:undefined ?' ||
                                            secondInputValue == null ||
                                            secondInputValue === " " ||
                                            secondInputValue === "" ||
                                            secondInputValue === '00000000-0000-0000-0000-000000000000' ||
                                            secondInputValue === '?' ||
                                            (Array.isArray(secondInputValue)));
                                        if (firstInputHasValue && secondInputHasValue) {
                                            input.parent('div').parent('div').removeClass('error has-error');
                                            input.parent('div').removeClass('error has-error');
                                        }
                                    }
                                } else {
                                    input.parent('div').removeClass('error has-error');
                                }
                            }
                        }
                    });
                    if (e.isDefaultPrevented() && $elm.attr('action') !== undefined) {
                        console.debug('default prevented');
                    } else {
                        var result = scope.ngBeforeSubmit();
                        return result;
                    }
                });
            }
        }
    };
});
