Dargah.controller("RegisterSummaryControler", function ($scope, $http, toaster, $rootScope, $state, $uibModalInstance) {
    $scope.SendRegisterRetryForAccept = function (RegisterFinished) {
        //if (confirm('آیا از ارسال اطلاعات جهت بررسی اطلاعات اطمینان دارید؟'))
        $scope.DisableSendBtn = true;
        $http.post('/Home/SendRegisterRetryForAccept').then(function successCallback(res) {
            if (res.data.success) {
                $scope.data.RegisterConfirmed = null;
                if (RegisterFinished === true) {
                    $scope.data.RegisterFinished = true;
                }
                //window.location = "/";
                $state.go('Portal', {}, { reload: true })
            }
            else {
                toaster.pop('error', "", 'امکان ارسال اطلاعات وجود ندارد');
                $scope.DisableSendBtn = false;
                return;
            }
        }, function errorCallback(res) {
            toaster.pop('error', ErrorMessage, AlertEroorCommand);
        });
    }
    $rootScope.$on("CallAdditionalDataMethod", function () {
        $scope.parentmethod();
    });
    $scope.parentmethod = function () {
        $scope.LoadData();
    }
    $scope.LoadData = function () {
        if ($rootScope.isGetHomeDataAlreadyLoaded) {
            //// ---- >>>> this scope has been written to avoide several request
            $scope.data = $rootScope.responseDataInGetHomeData;
            var Counter = 0
            Counter = $scope.data.Forms.length;
            $scope.DivCount = Counter;
            $scope.LoadingSumery = true;
        } else {
            //// ---- >>>> we load GetHomeData only when we had an error portal/home 
            $http.post('/Home/GetHomeData').then(function successCallback(res) {
                $scope.data = res.data.data.data;
                var Counter = 0
                Counter = $scope.data.data.Forms.length;
                $scope.DivCount = Counter;
                $scope.LoadingSumery = true;
            }, function errorCallback(res) {
                toaster.pop('error', ErrorMessage, AlertEroorCommand);
            });
        }
    }
    $scope.closefrm = function () {
        $uibModalInstance.close();
        $scope.modal.close()
    }
    $scope.cancel = function () {
        $uibModalInstance.dismiss('cancel');
    }
    $scope.LoadData();
});
