Dargah.controller('articleCtrl', function ($scope, $http, $uibModal, $stateParams) {
    $scope.gridConfig = (function () {
        var instance = {};
        var articleCategory = "";
        if ($stateParams !== null && $stateParams !== undefined)
            if ($stateParams.cat !== null && $stateParams.cat !== undefined)
                articleCategory = $stateParams.cat;
        instance.data = [];
        instance.totalCount = 0;
        instance.paging = {
            pageIndex: 1, pageSize: 10,
            sortField: '', sortDescending: true
        };
        instance.pagingPages = [];
        instance.pageSizeList = [10, 20, 50, 100];
        instance.searchModel = {};
        instance.columns = [];
        instance.load = () => {
            $http.post('/Articles/GetArticles', { gvRequest: instance.paging, cat: articleCategory }).then(function successCallback(res) {
                res.data = eval('(' + res.data.data + ')');
                if (res.data) {
                    // افزودن ردیف
                    for (var i = 0; i < res.data.length; i++)
                        res.data[i]._rowNumber = ((res.pageIndex - 1) * instance.paging.pageSize) + i + 1;

                    instance.columns = res.fields;
                    instance.data = res.data;
                    instance.totalCount = res.totalCount;
                    $scope.chartdata = res.data;
                } else {
                    instance.data = [];
                    if (res.fields)
                        instance.columns = res.fields;
                    if (res.totalCount)
                        instance.totalCount = res.totalCount;
                }
            }, function errorCallback(res) {
                toaster.pop('error', ErrorMessage, AlertEroorCommand);
            });
        };
        instance.sort = (fieldName) => {
            if (instance.paging.sortField === fieldName)
                instance.paging.sortDescending = !instance.paging.sortDescending;
            else {
                instance.paging.sortField = fieldName;
                instance.paging.sortDescending = false;
            }
            instance.load();
        };
        instance.load();
        return instance;
    })();
    // $scope.Category = null;
    $scope.loadGroup = function () {
        $http.post('/Articles/GetArticleGroup').then(function successCallback(res) {
            $scope.Grouplist = res.data.data;
            //$scope.Grouplist.push({ ID: null, Name: "همه دسته ها" });
        });
    };
    $scope.Search = function (category) {
        $scope.CategoryID = category === 0 ? '' : category;
        if ($stateParams !== null) {
            if ($stateParams.cat !== null)
                $stateParams = null;
            $scope.gridConfig.load();
        }
    };
    $scope.loadGroup();
});
Dargah.controller('articledetailCtrl', function ($scope, $http, $uibModal, $stateParams, $sce, $rootScope, $location) {
    $rootScope.ActiveAddress = $location.path();
    $http.post('/articles/getdetail/', { 'id': $stateParams.id }).then(function successCallback(data) {
        $scope.model = data.data.Result;
        $scope.model.Brief = $sce.trustAsHtml($scope.model.Brief);
    });
});
Dargah.controller('qualitativeCtrl', function ($scope, $http, $uibModal, $stateParams, toaster, $filter, $rootScope, $location) {
    $rootScope.ActiveAddress = $location.path();
    //$scope.ActiveAddress = $rootScope.ActiveAddress;
    $scope.SelectedItems = [];
    $scope.Type = $stateParams.type;
    if ($stateParams.saved === '1') {
        notifyShow(success, 2);
    }
    if ($stateParams.saved === '0') {
        notifyShow(AlertRequireUpload, 0);
    }
    $scope.IsJson = function (str) {
        try {
            JSON.parse(str);
        } catch (e) {
            return false;
        }
        return true;
    }
    $scope.FileUpload = function (id) {
        document.getElementById(id).click();
    }
    $scope.fileSelected = function (element) {
        var myFileSelected = element.files[0];
        if (myFileSelected) {
            document.getElementById("upload" + element.id).style.display = "none";
            document.getElementById("selected" + element.id).style.display = "block";
        }
        else {
            document.getElementById("selected" + element.id).style.display = "none";
            document.getElementById("upload" + element.id).style.display = "block";
        }
    };
    function scrollToFirstInvalid() {
        var $invalid = $('#frm')
            .find('.ng-invalid[required], .ng-invalid-required, .has-error input, .has-error select, .has-error textarea') .filter(':visible').first();

        if ($invalid.length === 0) {
            return;
        }

        var fixedOffset = 230; 
        var targetTop = $invalid.offset().top - fixedOffset;


        $('html, body').animate({ scrollTop: Math.max(targetTop, 2) }, 200);
    }

    $scope.submit = function () {
        var IsSave = true;
        var input = $('input[name="IsSave"]').val();
        if (input === 'true' || $scope.data.EvaluationType == 'with-simultaneous') {
            angular.forEach($filter('filter')($scope.data.EvaluationStandardMinors, { InputMethod: 'table' }), function (i) {
                var EvaluationEntriesfields = $filter('filter')($scope.data.EvaluationEntries, { StandardMinorID: i.ID, IsDocument: false });
                var EvaluationEntriesdocs = $filter('filter')($scope.data.EvaluationEntries, { StandardMinorID: i.ID, IsDocument: true });
                var fields = $filter('filter')($scope.data.EvaluationFields, { StandardMinorID: i.ID });
                var docs = $filter('filter')($scope.data.EvaluationDocuments, { StandardMinorID: i.ID });
                if (EvaluationEntriesfields.length > i.CountMax && i.CountMax !== null && fields.length > 0) {
                    IsSave = false;
                    notifyShow('حداکثر تعداد وارد شده برای معیار' + i.Name + ' ' + i.CountMax + ' مورد می باشد ', 0);
                    return false;
                }
                else if (EvaluationEntriesfields.length < i.CountMin && i.CountMin !== null && fields.length > 0) {
                    IsSave = false;
                    notifyShow(' حداقل تعداد وارد شده برای معیار' + i.Name + ' ' + i.CountMin + ' مورد می باشد  ', 0);
                    return false;
                }
                if (EvaluationEntriesdocs.length > i.CountMax && i.CountMax !== null && docs.length > 0) {
                    IsSave = false;
                    notifyShow('حداکثر تعداد فایل وارد شده برای معیار' + i.Name + ' ' + i.CountMax + ' مورد می باشد ', 0);
                    return false;
                }
                else if (EvaluationEntriesdocs.length < i.CountMin && i.CountMin !== null && docs.length > 0) {
                    IsSave = false;
                    notifyShow(' حداقل تعداد فایل وارد شده برای معیار' + i.Name + ' ' + i.CountMin + ' مورد می باشد  ', 0);
                    return false;
                }
            });

            var Selected = [];
            for (var i of Object.keys($scope)) {
                if (i.startsWith('Additional:')) {
                    var item = document.getElementById(i);
                    if (item && item.checked) {
                        var list = item.id.split(':');
                        Selected.push({ Type: list[1], minorID: list[2], AdditionalID: list[3] });
                    }
                }
            }
            angular.forEach($filter('filter')($scope.data.EvaluationStandardMinors, { InputMethod: 'additional' }), function (i) {
                var Data = [];
                switch (i.AdditionalSource) {
                    case 'Member':
                        Data = $filter('filter')(Selected, { Type: 'Member', minorID: i.ID });
                        break;
                    case 'Project':
                        Data = $filter('filter')(Selected, { Type: 'Project', minorID: i.ID });
                        break;
                    case 'Equipment':
                        Data = $filter('filter')(Selected, { Type: 'Equipment', minorID: i.ID });
                        break;
                    case 'Material':
                        Data = $filter('filter')(Selected, { Type: 'Material', minorID: i.ID });
                        break;
                    case 'Branch':
                        Data = $filter('filter')(Selected, { Type: 'Branch', minorID: i.ID });
                        break;
                    case 'Field':
                        Data = $filter('filter')(Selected, { Type: 'Field', minorID: i.ID });

                        break;
                    case 'Category':
                        Data = $filter('filter')(Selected, { Type: 'Category', minorID: i.ID });
                        break;
                    case 'Certificate':
                        Data = $filter('filter')(Selected, { Type: 'Certificate', minorID: i.ID });
                        break;
                    case 'Contracts':
                        Data = $filter('filter')(Selected, { Type: 'Contracts', minorID: i.ID });
                        break;
                }
                if (Data.length > i.CountMax && i.CountMax !== null) {
                    IsSave = false;
                    notifyShow('حداکثر تعداد وارد شده برای معیار ' + i.Name + ' ' + i.CountMax + ' مورد می باشد ', 0);
                    return false;
                }
                else if (Data.length < i.CountMin && i.CountMin !== null) {
                    IsSave = false;
                    notifyShow('حداقل تعداد وارد شده برای معیار ' + i.Name + ' ' + i.CountMin + ' مورد می باشد  ', 0);
                    return false;
                }
            });
        }
        if (IsSave /*|| $scope.data.EvaluationType == 'with-simultaneous'*/) {
            return true;
        }
        scrollToFirstInvalid();
        return false;
    }
    $(document).on('click', '#frm button[type=submit]', function () {
        setTimeout(scrollToFirstInvalid,30);
    });
    $scope.Save = function (val) {
        $('input[name="IsSave"]').val(val);
    }
    
    $scope.GetEvaluation = function () {
        $scope.loading = true;
        $http.post('/Evaluation/GetEvaluationData', { 'id': $stateParams.ID, type: $stateParams.type }).then(function successCallback(data) {
            $scope.data = data.data.data;
            angular.forEach($scope.data.EvaluationEntries, function (e) {
                e.Values = $scope.IsJson(e.Values) ? JSON.parse(e.Values) : e.Values;
            });
            try {
                for (var major of $scope.data.EvaluationStandardMajors) {
                    for (var minor of $filter('filter')($scope.data.EvaluationStandardMinors, { StandardMajorID: major.ID })) {
                        if (minor.InputMethod == 'additional') {
                            switch (minor.AdditionalSource) {
                                case 'Member':
                                    {
                                        if ($scope.data.Additional_Members != null) {
                                            for (var i of $scope.data.Additional_Members) {
                                                $scope['Additional:Members:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = false;
                                                for (var e of $scope.data.EvaluationEntries) {
                                                    if (e.AdditionalID === i.ID && minor.ID == e.StandardMinorID) {
                                                        $scope['Additional:Members:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = true;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                        break;
                                    }
                                case 'Project':
                                    {
                                        if ($scope.data.Additional_Projects) {
                                            for (var i of $scope.data.Additional_Projects) {
                                                $scope['Additional:Project:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = false;
                                                for (var e of $scope.data.EvaluationEntries) {
                                                    if (e.AdditionalID === i.ID && minor.ID == e.StandardMinorID) {
                                                        $scope['Additional:Project:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = true;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                        break;
                                    }
                                case 'Equipment':
                                    {
                                        if ($scope.data.Additional_Equipments != null) {
                                            for (var i of $scope.data.Additional_Equipments) {
                                                $scope['Additional:Equipment:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = false;
                                                for (var e of $scope.data.EvaluationEntries) {
                                                    if (e.AdditionalID === i.ID && minor.ID == e.StandardMinorID) {
                                                        $scope['Additional:Equipment:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = true;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                        break
                                    }
                                case 'Branch':
                                    {
                                        if ($scope.data.Additional_Branches != null) {
                                            for (var i of $scope.data.Additional_Branches) {
                                                $scope['Additional:Branch:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = false;
                                                for (var e of $scope.data.EvaluationEntries) {
                                                    if (e.AdditionalID === i.ID && minor.ID == e.StandardMinorID) {
                                                        $scope['Additional:Branch:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = true;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                        break
                                    }
                                case 'Field':
                                    {
                                        if ($scope.data.Additional_Fields) {
                                            for (var i of $scope.data.Additional_Fields) {
                                                $scope['Additional:Field:' + minor.ID + ':' + i.ID.toString()] = false;
                                                for (var e of $scope.data.EvaluationEntries) {
                                                    if (e.AdditionalID === i.ID.toString() && minor.ID == e.StandardMinorID) {
                                                        $scope['Additional:Field:' + minor.ID + ':' + i.ID.toString()] = true;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                        break
                                    }
                                case 'Category':
                                    {
                                        if ($scope.data.Additional_Categories != null) {
                                            for (var i of $scope.data.Additional_Categories) {
                                                $scope['Additional:Category:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = false;
                                                for (var e of $scope.data.EvaluationEntries) {
                                                    if (e.AdditionalID === i.ID && minor.ID == e.StandardMinorID) {
                                                        $scope['Additional:Category:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = true;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                        break
                                    }
                                case 'Certificate':
                                    {
                                        if ($scope.data.Additional_Certificates) {
                                            for (var i of $scope.data.Additional_Certificates) {
                                                $scope['Additional:Certificate:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = false;
                                                for (var e of $scope.data.EvaluationEntries) {
                                                    if (e.AdditionalID === i.ID && minor.ID == e.StandardMinorID) {
                                                        $scope['Additional:Certificate:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = true;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                        break
                                    }
                                case 'Contracts':
                                    {
                                        if ($scope.data.Additional_Contracts != null) {
                                            for (var i of $scope.data.Additional_Contracts) {
                                                $scope['Additional:Contracts:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = false;
                                                for (var e of $scope.data.EvaluationEntries) {
                                                    if (e.AdditionalID === i.ID && minor.ID == e.StandardMinorID) {
                                                        $scope['Additional:Contracts:' + minor.ID + ':' + i.ID.replaceAll('-', '_')] = true;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                        break
                                    }
                            }

                        }
                    }
                }
            }
            catch (er) {
                console.log(er);
            }
            if ($scope.data.EvaluationFields != null) {
                angular.forEach($scope.data.EvaluationFields, function (i) {
                    i.DropdownItems = JSON.parse(i.DropdownItems);
                    angular.forEach($scope.data.EvaluationEntries, function (e) {
                        if (e.StandardMinorID === i.StandardMinorID) {
                            var Values = e.Values;
                            var valEntry = JSON.stringify(e.Values);
                            var val = valEntry.includes("fld_" + i.ID) ? e.Values["fld_" + i.ID] : e.Values["fld" + i.ID];
                            if (i.IsDropdown === 'Y' && i.DropdownItems !== null) {
                                var dropdownItems = i.DropdownItems;
                                val = dropdownItems[val];
                            }
                            i.Value = val;
                        }
                    });
                });
            }
            if ($scope.data.EvaluationChecklists != null) {
                angular.forEach($scope.data.EvaluationChecklists, function (chl) {
                    chl.checklistValues = JSON.parse(chl.Values);
                    angular.forEach($scope.data.EvaluationEntries, function (e) {
                        var val = e.Values.toString();
                        if (val.startsWith("chl_" + chl.ID) && e.minorID === chl.minorID) {
                            chl.EncriptID = e.EncriptID;
                            chl.EntryValues = !val ? [] :
                                JSON.parse(val.substr(val.indexOf("|") + 1));
                        }
                    });
                    if ($scope.data.EvaluationFields != null) {
                        angular.forEach($scope.data.EvaluationFields, function (i) {
                            if (chl.StandardMinorID === i.StandardMinorID) {
                                //if (chl.EntryValues!==null)
                                i.Value = chl.checklistValues['fld_' + i.ID];
                            }
                        });
                    }
                });
            }
            $scope.loading = false;
        });
    };
    $scope.GetEvaluation();
    $scope.editCustomDocRecord = function (minorID, entryID) {
        $scope.docs = [];
        angular.forEach($scope.data.EvaluationDocuments, function (i) {
            if (minorID === i.StandardMinorID) {
                if (entryID !== 0) {
                    angular.forEach($scope.data.EvaluationEntries, function (e) {
                        if (e.ID === entryID) {
                            var valEntry = JSON.stringify(e.Values);
                            var val = valEntry.includes("fld_" + i.ID) ? e.Values["fld_" + i.ID] : e.Values["fld" + i.ID];
                            i.Value = val;
                        }
                    });
                }
                else { i.Value = ''; }
                $scope.docs.push(i);
            }
        });
        $uibModal.open({
            animation: true,
            templateUrl: '/templates/evaluation/edit-minor-doc.html',
            controller: 'modalCtrl',
            size: 'lg',
            resolve: {
                minorID: () => minorID,
                docs: () => $scope.docs,
                fields: () => [],
                entryID: () => entryID
            }
        }).result.then(function (r) {
            $scope.loading = true;
            $http.post('/Evaluation/GetEvaluationData', { 'id': $stateParams.ID, type: $stateParams.type })
                .then(function successCallback(data) {
                    $scope.data.EvaluationEntries = data.data.data.EvaluationEntries;
                    $scope.loading = false;
                    angular.forEach($scope.data.EvaluationEntries, function (e) {
                        e.Values = $scope.IsJson(e.Values) ? JSON.parse(e.Values) : e.Values;
                    });
                });
            //$scope.GetEvaluation();
        });
    };
    $scope.editCutomeRecord = function (minorID, entryID) {
        var IsSave = true;
        if (entryID === 0) {
            angular.forEach($filter('filter')($scope.data.EvaluationStandardMinors, { InputMethod: 'table', ID: minorID }), function (i) {
                var EvaluationEntriesfields = $filter('filter')($scope.data.EvaluationEntries, { StandardMinorID: minorID, IsDocument: false });
                if (EvaluationEntriesfields.length >= i.CountMax && i.CountMax !== null) {
                    IsSave = false;
                    toaster.pop('error', "", 'حداکثر تعداد وارد شده برای معیار' + i.Name + ' ' + i.CountMax + ' مورد می باشد ');
                    return false;
                }
            });
        }
        $scope.fields = [];
        angular.forEach($scope.data.EvaluationFields, function (i) {
            //i.DropdownItems = JSON.parse(i.DropdownItems);
            if (minorID === i.StandardMinorID) {
                if (entryID !== 0) {
                    angular.forEach($scope.data.EvaluationEntries, function (e) {
                        if (e.ID === entryID) {
                            var Values = e.Values;
                            var valEntry = JSON.stringify(e.Values);
                            var val = valEntry.includes("fld_" + i.ID) ? e.Values["fld_" + i.ID] : e.Values["fld" + i.ID];
                            if (i.IsDropdown === 'Y' && i.DropdownItems !== null) {
                                var dropdownItems = i.DropdownItems;
                                angular.forEach(dropdownItems, function (d) {
                                    if (d.Key === val)
                                        i.Value = d.Value;
                                });
                            }
                            else i.Value = val;
                        }
                    });
                }
                else { i.Value = ''; }
                $scope.fields.push(i);
            }
        });
        if (IsSave) {
            $uibModal.open({
                animation: true,
                //class: "modal-dialog-centered",
                templateUrl: '/templates/evaluation/edit-minor.html',
                controller: 'modalCtrl',
                size: 'lg',
                resolve: {
                    minorID: () => minorID,
                    fields: () => $scope.fields,
                    docs: () => [],
                    entryID: () => entryID,
                }
            }).result.then(function (r) {
                $http.post('/Evaluation/GetEvaluationData', { 'id': $stateParams.ID, type: $stateParams.type })
                    .then(function successCallback(data) {
                        $scope.data.EvaluationEntries = data.data.data.EvaluationEntries;
                        $scope.loading = false;
                        angular.forEach($scope.data.EvaluationEntries, function (e) {
                            e.Values = $scope.IsJson(e.Values) ? JSON.parse(e.Values) : e.Values;
                        });
                    });
            });
        }
    };
    $scope.remove = function (ID, Type) {
        if (confirm(AlertRemove))
            $http.post('/evaluation/Remove?id=' + ID + '&&Type=' + Type).then(function successCallback(res) {
                if (res.data.success) {
                    toaster.pop('success', "", AlertSuccessRemove);
                    $http.post('/Evaluation/GetEvaluationData', { 'id': $stateParams.ID, type: $stateParams.type })
                        .then(function successCallback(data) {
                            $scope.data.EvaluationEntries = data.data.data.EvaluationEntries;
                            $scope.loading = false;
                            angular.forEach($scope.data.EvaluationEntries, function (e) {
                                e.Values = $scope.IsJson(e.Values) ? JSON.parse(e.Values) : e.Values;
                            });
                        });
                }
                else
                    toaster.pop("error", "", AlertErrorFetching);
            });
    };
    $scope.IsCheked = function (minor, i, Type) {
        if ($scope['Additional:' + Type + ':' + minor.ID + ':' + i.ID.toString().replaceAll('-', '_')])
            return true;
        else
            return false;
    }
});
Dargah.controller('modalCtrl', function ($scope, $http, $uibModalInstance, minorID, entryID, fields, docs, toaster) {
    $scope.minorID = minorID;
    $scope.entryID = entryID;
    $scope.fields = fields;
    $scope.docs = docs;
    $scope.convertToEnglishDate = function (date) {
        var output = moment.from(date, 'fa', 'YYYY/MM/DD').locale('en').format('YYYY-MM-DD');
        return output;
    }
    $scope.convertToPersianDate = function (date) {
        return moment(date, 'YYYY/MM/DD').locale('fa').format('YYYY/MM/DD');
    }
    $scope.FileUpload = function (id) {
        document.getElementById(id).click();
    }
    $scope.fileSelected = function (element) {
        var myFileSelected = element.files[0];
        if (myFileSelected) {
            document.getElementById("upload" + element.id).style.display = "none";
            document.getElementById("selected" + element.id).style.display = "block";
        }
        else {
            document.getElementById("selected" + element.id).style.display = "none";
            document.getElementById("upload" + element.id).style.display = "block";
        }

    };
    if (entryID !== 0) {
        //$http.post()
    }
    $scope.cancel = function () {
        $uibModalInstance.dismiss('cancel');
    };
    $scope.submitfield = function () {
        $scope.disable = true;
        var fd = new FormData();
        angular.forEach($scope.fields, function (fld) {
            if (fld.DataType === 'file') {
                var fileUpload = $('#fld_' + fld.ID).get(0);
                if (fileUpload.files.length > 0) {
                    var files = fileUpload.files[0];
                    fd.append('fld_' + fld.ID, files);
                }
                else fd.append('fld_' + fld.ID, fld.Value);
            }
            else {
                fd.append('fld_' + fld.ID, fld.Value);
            }
        });
        $http.post('/Evaluation/PostCustomValues?MinorID=' + $scope.minorID + '&EntryID=' + $scope.entryID + '&TenderID=' + $scope.TenderID + '&Type=' + $scope.Type, fd, {
            transformRequest: angular.identity,
            headers: { 'Content-Type': undefined }
        }).then(function successCallback(res) {
            $scope.disable = false;
            if (!res.data.success) {
                toaster.pop('error', "", UploadErrorMessage);
                return;
            }
            else {
                toaster.pop('success', "", success);
                $uibModalInstance.close();
            }
        });
    };
    $scope.submit = function () {
        $scope.disable = true;
        var fd = new FormData();
        angular.forEach($scope.docs, function (fld) {
            var fileUpload = $('#fld_' + fld.ID).get(0);
            var files = fileUpload.files[0];
            fd.append('fld_' + fld.ID, files);
        });
        $http.post('/Evaluation/postDocsValues?MinorID=' + $scope.minorID + '&EntryID=' + $scope.entryID + '&TenderID=' + $scope.TenderID + '&Type=' + $scope.Type, fd, {
            transformRequest: angular.identity,
            headers: { 'Content-Type': undefined }
        }).then(function successCallback(res) {
            $scope.disable = false;
            if (!res.data.success) {
                toaster.pop('error', "", UploadErrorMessage);
                return;
            }
            else {
                toaster.pop('success', "", success);
                $uibModalInstance.close();
            }
        });
    };
});
Dargah.controller('ProfileCtrl', function ($scope, $http, $uibModal, toaster, FieldService, $state, $location, $rootScope, $parse) {
    $rootScope.ActiveAddress = $location.path();
    $scope.selectedCountry = "";
    $scope.getdata = function () {

        $scope.loading = true;
        $http.post('/Profile/GetData/').then(function successCallback(data) {
            data = data.data.data;
            $scope.CountryID = data.countries.find(x => x.Default).ID
            if (data.FoundationDate.length !== 0) {
                data.Contractor.FoundationDate = data.FoundationDate;
            }
            $scope.Contractor = data.Contractor;
            $scope.model = {};
            $scope.model.contractorFields = $scope.Contractor.Fields;
            $scope.viewerMan = FieldService($scope.model.contractorFields, $scope.tableID, $scope);
            $scope.viewerMan.TagBoxes($parse).map((item) => { $scope["tagBoxFormField_" + item.ID] = item });
            $scope.Activity = data.Activity;
            if (data.Contractor.actv !== null && data.Contractor.actv) {
                data.Contractor.actv = data.Contractor.actv.map((c) => { c.Key = Number(c.Key); return c; });
            }
            $scope.provinces = data.Provinces;
            $scope.countries = data.countries;
            $scope.actv = data.Contractor.actv;
            $scope.RegisterConfirmed = data.Contractor.RegisterConfirmed;
            $scope.cities = data.Cities;
            $scope.cities.push({ ID: 0, Name: 'انتخاب ' });
            $scope.documentsList = data.documentsList;
            $scope.CanEdit = data.CanEdit;
            $scope.IsShowRequestEditForm = data.IsShowRequestEditForm;
            $scope.Banks = data.Banks;
            $scope.loading = false;
            $scope.tagBox = {
                customTemplate: {
                    onInitialized(e) {
                        // Preserve existing behavior for Activity (string) if needed
                        if ($scope.Contractor.Activity2 && $scope.Contractor.Activity2.length > 0) {
                            $('input[name="Activity"]').val($scope.Contractor.Activity2.join(","));
                        }
                        // Ensure Activity2 exists as an array of numbers on model
                        if (Array.isArray($scope.Contractor.Activity2)) {
                            $scope.Contractor.Activity2 = $scope.Contractor.Activity2.map(Number);
                        } else {
                            $scope.Contractor.Activity2 = [];
                        }
                    },
                    dataSource: data.Contractor.actv,
                    displayExpr: 'Value',
                    valueExpr: 'Key',
                    placeholder: IsRtl ? 'نوع فعالیت (با امکان انتخاب چندین مورد)' : 'Select the type of activity ... ',
                    rtlEnabled: IsRtl,
                    onValueChanged(e) {
                        if (e.value.length > 0) {
                            $('input[name="Activity"]').val(e.value)
                            $('label[id="Activity-error"]').css("display", "none")
                        } else if (e.value.length == 0) {
                            $('input[name="Activity"]').val(null)
                        }
                        // set Activity2 on the model as an array of numbers
                        $scope.Contractor.Activity2 = (e.value || []).map(Number);
                        $scope.$applyAsync();
                    }
                },
            };
            $scope.selectedCountry = $("select[name='Contractor.CountryID']").val() == '' || $("select[name='Contractor.CountryID']").val() == null || $("select[name='Contractor.CountryID']").val() == undefined ? $scope.Contractor.CountryID : $("select[name='Contractor.CountryID']").val();
            $scope.HasActiveDigitalSignature = data.HasActiveDigitalSignature;

        });
    };
    $scope.changeCountryForMobileNumber = () => {
        $scope.selectedCountry = $("select[name='Contractor.CountryID']").val();
    }
    $scope.CheckEmail = function (email) {

        var EMAIL_REGEXP = /^[_a-z0-9]+(\.[_a-z0-9]+)*@@[a-z0-9-]+(\.[a-z0-9-]+)*(\.[a-z]{2,4})$/;
        var isMatchRegex = EMAIL_REGEXP.test(email);
        if (isMatchRegex) {
            $scope.Emailalert = false;
            return false;
        } else {
            $scope.Emailalert = true;
            return true;
        }
    }
    $scope.CheckEmailDB = function (isRequired) {
        if (!isRequired && ($scope.Contractor.Email == null || $scope.Contractor.Email.length == 0)) {
            return true;
        }
        $http.get('/Profile/checkEmail?email=' + $scope.Contractor.Email).then(function successCallback(res) {
            if (res.data.success) {
                if (res.data.data == false) {
                    $("input[name*='email']").closest('input').parent('div').addClass('has-error10');
                    return false;
                }
                else {
                    $("input[name*='email']").closest('input').parent('div').removeClass('has-error10');
                    return true;
                }
            }
        });

    }
    $scope.checkMobile = function () {
        $http.get('/Profile/CheckMobile?mobile=' + $scope.Contractor.Mobile).then(function successCallback(res) {
            if (res.data.success) {
                if (res.data.data == true) {
                    $("input[name*='mobile']").closest('input').parent('div').addClass('has-error10');
                    return false;
                }
                else {
                    $("input[name*='mobile']").closest('input').parent('div').removeClass('has-error10');
                    return true;
                }
            }
        });
    }
    $scope.getdata();
    $scope.removefile = function (file) {
        if ($scope.IsShowRequestEditForm) {
            $uibModal.open({
                animation: true,
                templateUrl: '/ng-templates/RequestEdit.html',
                controller: 'RequestEditCtrl',
                size: 'md',
                resolve: {
                    model: { Comment: '' }
                }
            }).result.then(function (modalResult) {

            });
        }
        else {
            if (confirm(AlertRemove))
                $http.post('/Profile/DeleteFile/' + file)
                    .then(function successCallback(data) {
                        toaster.pop('success', "", AlertSuccessRemove);
                        $scope.getdata();
                    });
        }
    };
    $scope.submit = function () {
        if ($('input[name="Activity"]').val() == '') {
            $('#contractorActivityTypeValidationID').css("border", "1px solid red");
        }
        if (!$scope.companyProfile.$$element[0].Valid) return false;
        if ($scope.IsShowRequestEditForm) {
            $uibModal.open({
                animation: true,
                templateUrl: '/ng-templates/RequestEdit.html',
                controller: 'RequestEditCtrl',
                size: 'md',
                resolve: {
                    model: { Comment: '' }
                }
            }).result.then(function (modalResult) { });
        }
        else {
            if ($("input[name*='mobile']").closest('input').parent('div').hasClass("has-error10")) {
                if ($("input[name*='mobile']").val() != "09") {
                    if (IsRtl) {
                        DevExpress.ui.notify({ message: "تلفن همراه وارد شده تکراری است", width: 450, shading: false }, "error", 2000);
                    } else if (!IsRtl) {
                        DevExpress.ui.notify({ message: "The mobile number has been registered", width: 450, shading: false }, "error", 2000);
                    }
                    return false;
                } else if ($("input[name*='mobile']").val() == "09") {
                    if (IsRtl) {
                        DevExpress.ui.notify({ message: "تلفن همراه وارد نشده است", width: 450, shading: false }, "error", 2000);
                    } else if (!IsRtl) {
                        DevExpress.ui.notify({ message: "Please enter mobile number", width: 450, shading: false }, "error", 2000);
                    }
                    return false;
                }
            }
            if ($("input[name*='email']").closest('input').parent('div').hasClass("has-error10")) {
                if ($("input[name*='email']").val() == "") {
                    if (IsRtl) {
                        DevExpress.ui.notify({ message: "ایمیل وارد نشده است", width: 450, shading: false }, "error", 2000);
                    } else if (!IsRtl) {
                        DevExpress.ui.notify({ message: "Please enter email address", width: 450, shading: false }, "error", 2000);
                    }
                } else if ($("input[name*='email']").val() != "") {
                    if (IsRtl) {
                        DevExpress.ui.notify({ message: " ایمیل وارد شده تکراری است", width: 450, shading: false }, "error", 2000);
                    } else if (!IsRtl) {
                        DevExpress.ui.notify({ message: "The email address has been registered", width: 450, shading: false }, "error", 2000);
                    }
                }
                return false;
            }
            $scope.ListActivities = [];
            if (!$scope.companyProfile.$$element[0].Valid) {
                return;
            }
            $scope.viewerMan = FieldService($scope.Contractor.Fields, $scope.Contractor.ID);
            if ($scope.viewerMan.valid() === false) {
                $scope.disable = false;
                return false;
            }
            $scope.Contractor.JsonFields = JSON.stringify($scope.viewerMan.data());
            var fileData = new FormData();
            angular.forEach($scope.ListActivity, function (i) {
                $scope.ListActivities.push(i.Key)
            });
            if (Array.isArray($scope.Contractor.Activity2)) {
                // Option A (indexed keys) - safest across MVC versions
                $scope.Contractor.Activity2.forEach((val, idx) => {
                    fileData.append(`Activity2[${idx}]`, parseInt(val, 10));
                });
            }
            

            $scope.Contractor.Activity = $scope.ListActivities;
            fileData.append("ID", $scope.Contractor.ID);
            fileData.append("Name", $scope.Contractor.Name ? $scope.Contractor.Name : '');
            fileData.append("Type", $scope.Contractor.Type ? $scope.Contractor.Type : '');
            fileData.append("DUNS", $scope.Contractor.DUNS ? $scope.Contractor.DUNS : '');
            fileData.append("Logo", $("#Logo").val());
            fileData.append("NationalCode", $scope.Contractor.NationalCode ? $scope.Contractor.NationalCode : '');
            fileData.append("RegistrationNumber", $scope.Contractor.RegistrationNumber ? $scope.Contractor.RegistrationNumber : '');
            fileData.append("RegistrationAddress", $scope.Contractor.RegistrationAddress ? $scope.Contractor.RegistrationAddress : '');
            fileData.append("EconomicCode", $scope.Contractor.EconomicCode ? $scope.Contractor.EconomicCode : '');
            fileData.append("FoundationDate", $scope.Contractor.FoundationDate ? $scope.Contractor.FoundationDate : '');
            fileData.append("CeoName", $scope.Contractor.CeoName ? $scope.Contractor.CeoName : '');
            fileData.append("CeoNationalCode", $scope.Contractor.CeoNationalCode ? $scope.Contractor.CeoNationalCode : '');
            fileData.append("CeoMobile", $scope.Contractor.CeoMobile ? $scope.Contractor.CeoMobile : '');
            fileData.append("Phone", $scope.Contractor.Phone ? $scope.Contractor.Phone : '');
            fileData.append("PrePhone", $scope.Contractor.PrePhone ? $scope.Contractor.PrePhone : '');
            fileData.append("Mobile", $scope.Contractor.Mobile ? $scope.Contractor.Mobile : '');
            fileData.append("PostalCode", $scope.Contractor.PostalCode ? $scope.Contractor.PostalCode : '');
            fileData.append("Fax", $scope.Contractor.Fax ? $scope.Contractor.Fax : '');
            fileData.append("Email", $scope.Contractor.Email ? $scope.Contractor.Email : '');
            fileData.append("InsuranceBranch", $scope.Contractor.InsuranceBranch ? $scope.Contractor.InsuranceBranch : '');
            fileData.append("BankAccount", $scope.Contractor.BankAccount ? $scope.Contractor.BankAccount : '');
            fileData.append("BranchAccount", $scope.Contractor.BranchAccount ? $scope.Contractor.BranchAccount : '');
            fileData.append("ShabaNumber", $scope.Contractor.ShabaNumber ? $scope.Contractor.ShabaNumber : '');
            fileData.append("Address", $scope.Contractor.Address ? $scope.Contractor.Address : '');
            fileData.append("Website", $scope.Contractor.Website ? $scope.Contractor.Website : '');
            fileData.append("ProvinceID", $scope.Contractor.ProvinceID ? $scope.Contractor.ProvinceID : '');
            fileData.append("CityID", $scope.Contractor.CityID ? $scope.Contractor.CityID : '');
            fileData.append("CountryID", $scope.Contractor.CountryID ? $scope.Contractor.CountryID : '');
            fileData.append("Activity", $scope.Contractor.Activity ? $scope.Contractor.Activity : '');
            fileData.append("BankID", $scope.Contractor.BankID);
            fileData.append("JsonFields", $scope.Contractor.JsonFields);
            var rvt = angular.element('input[name="X-CSRF-Token"]').val();
            var httpConfig = { headers: { 'X-XSRF-Token': rvt } };
            $http.post('/Profile/save', fileData,
                {
                    transformRequest: angular.identity,
                    headers: { 'Content-Type': undefined }
                },
                httpConfig).then(function successCallback(res) {
                    res = res.data;
                    if (res.success) {
                        $scope.loading = true;
                        $scope.Contractor = res.data;
                        if ($scope.Contractor.Fields)
                            angular.forEach($scope.Contractor.Fields, function (j) {
                                var val = j.Value;
                                if (val !== null && j.DataType === "multiselect") {
                                    if (val.includes(','))
                                        j.Value = val.split(',');
                                    else j.Value = JSON.parse('["' + val + '"]');
                                }
                            })
                        notifyShow(IsRtl ? 'ثبت اطلاعات با موفقیت انجام شد' : 'Information registration was successful.', 2);
                        $state.go('Profile', {}, { reload: true })
                    }
                    else
                        notifyShow(res.redirect, 0);
                }, function errorCallback(res) {
                    notifyShow( ErrorMessage, 0);
                });
        }
    };
    $scope.RevokeCertificate = function () {
        $uibModal.open({
            animation: true,
            templateUrl: '/ng-templates/RevokeCertificate.html',
            controller: 'RevokeCertificateCtrl',
            size: 'lg'
            
        }).result.then(function (mr) {
            window.location.reload();
        });
    }
    $scope.Issuedcertificate = function () {
        $state.go('DigitalSignature');
    }

});
