Dargah.controller('bondModalCtrl', function ($scope, $uibModalInstance, $uibModal, externalInject) {
    if (externalInject && externalInject !== null) {
        for (let ei in externalInject) {
            $scope[ei] = externalInject[ei];
        }
    };
    $scope.Bond = $scope.Bond && $scope.Bond !== null ? $scope.Bond : {};
    $scope.CheckBondPrice = function () {
        var bondPriceTender = parseFloat($scope.TenderModel.BondPrice.replace(',', ''));
        var bondPrice = parseFloat($scope.Bond.Price.replace(',', ''));
        if (bondPriceTender != 0 && Number.isNaN(bondPriceTender) && Number.isNaN(bondPrice) && bondPrice < bondPriceTender) {
            toaster.pop('error', 'مبلغ تضمین وارد شده معتبر نمی باشد');
        }
    }
    $scope.selectBankAndBranch = function () {
        $uibModal.open({
            animation: true,
            templateUrl: '/bankAndBranchModal.html',
            controller: 'bankAndBranchModalCtrl',
            size: 'lg',
            resolve: {
                model: () => ({
                    bankID: $scope.Bond ? $scope.Bond.BankID : null,
                    branchID: $scope.Bond ? $scope.Bond.BankBranchID : null
                })
            }
        }).result.then(function (modalResult) {
            $scope.Bond.BankBranchID = modalResult.branchID;
            $scope.InfoBox.BankName = modalResult.name;
            $scope.Bond.bondGuaranteeUrl = modalResult.BondGuaranteeUrl;
        });
    };
    $scope.calculateEndDate = function () {
        if ((!$scope.Bond.Duration || !$scope.Bond.Duration__Unit) || ($scope.Bond.Duration.length === 0 || $scope.Bond.Duration__Unit.length === 0)) {
            $scope.Bond.EndDate = "";
            return;
        }
        var duration = parseInt($scope.Bond.Duration);
        duration = duration === 0 ? 0 : duration;
        let newDate = addToDate(addToDate($scope.Bond.StartDate, $scope.Bond.Duration__Unit, duration), "d", -1);
        if (newDate === "Invalid date")
            $scope.Bond.EndDate = "";
        else
            $scope.Bond.EndDate = newDate;
    }
    $scope.clearSelect = function (type) {
        if (confirm('آیا از حذف این مورد اطمینان دارید؟') == false) return;
        if (type == 'bond') {
            $scope.Bond.BankBranchID = '';
            $scope.InfoBox.BankName = '';
            $("input[name='InfoBoxBankName']").val("")
        }
    };
    $scope.submit = async function () {

        var res = await fetchPost('/deals/SaveBond', { id: $scope.TenderContractor.ID, bond: $scope.Bond })
        if (res.success) {
            notifyShow('عملیات موفقیت آمیز بود', 2)
            $uibModalInstance.close();
        } else {
            notifyShow('خطا', 0)
        }

    };
    $scope.cancel = function () {
        $uibModalInstance.dismiss('cancel');
    };
});
