Dargah.controller('templateSelectAttachmentModalCtrl', function ($scope, $http, $uibModal, $uibModalInstance, toaster, Upload, archiveViewerManagerService, archiveParams, parentID, SweetAlert, Title) {
    // archive
    $scope.uploading = false;
    $scope.uploadProgress = 0;
    $scope.uploadItems = [];
    $scope.uploadErrors = [];
    $scope.Title = Title;
    $scope.upload = function (selectedFiles) {
        if (selectedFiles && selectedFiles.length > 0) {
            $scope.uploading = true;
            $scope.uploadItems = [];
            if (angular.isArray(selectedFiles)) {
                angular.forEach(selectedFiles, function (i) {
                    $scope.uploadItems.push({ file: i, progress: 0, done: false });
                });
            }
            else
                $scope.uploadItems.push({ file: selectedFiles, progress: 0, done: false });
            angular.forEach($scope.uploadItems, function (i) {
                var upload = Upload.upload({
                    method: 'POST', url: '/templates/show/uploadAttachment/' + params.renderID,
                    //fields: $scope.model,
                    file: i.file
                }).progress(function (evt) {
                    i.progress = Math.min(100, parseInt(100.0 * evt.loaded / evt.total));
                    updateProgressbar();
                }).then(function successCallback(res) {
                    if (res.data.data.success) i.result = res.data.data.data;
                    else $scope.uploadErrors.push({ name: i.file.name, text: 'شما مجوز لازم برای ذخیره در این را ندارید.' });
                    i.done = true;
                    checkUploadsDone();
                });
            });
        }
    };
    $scope.archiveScope = { FileList: [], FolderList: [], view: 'grid', Path: '', CurrentData: null, loading: true, parentID: parentID, FolderCount: 0, FileCount: 0, FileIndex: 50, FolderIndex: 50, uploadProgress: 0, setpage: 1 };
    $scope.archiveMan = archiveViewerManagerService(archiveParams, $scope.archiveScope);
    $scope.archiveMan.load();
    $scope.deletefile = function () {
        var ids = [];
        angular.forEach($scope.archiveScope.FolderList, function (i) {
            if (i._checked) ids.push(i.ID);
        });
        angular.forEach($scope.archiveScope.FileList, function (i) {
            if (i._checked) ids.push(i.ID);
        });
        if (ids.length > 0) {
            if (confirm(AlertRemove))
                $http.post('/archivemanager/deleteFiles/' + archiveParams.section + '/' + archiveParams.objectID, { ids: ids }).then(function successCallback(res) {
                    if (res.data.success) {
                        $scope.archiveMan.load();
                        toaster.pop('success', '', AlertSuccessRemove);
                        $scope.viewerMan.load();
                    }
                });
        }
    };
    $scope.cancel = function () {
        $uibModalInstance.close();
    };
    $scope.$watch('uploadSelectedFiles', function (selectedFiles) {
        if (selectedFiles && selectedFiles.length > 0) {
            $scope.uploading = true;
            $scope.uploadItems = [];
            if (angular.isArray(selectedFiles)) {
                angular.forEach(selectedFiles, function (i) {
                    $scope.uploadItems.push({ file: i, progress: 0, done: false });
                });
            }
            else
                $scope.uploadItems.push({ file: selectedFiles, progress: 0, done: false });
            angular.forEach($scope.uploadItems, function (i) {
                var upload = Upload.upload({
                    method: 'POST', url: '/archivemanager/postFile/' + archiveParams.section + '/' + archiveParams.objectID + ($scope.archiveScope !== null ? '/' + $scope.archiveScope.parentID : ''),
                    //headers: {
                    //    'my-header': 'my-header-value'
                    //},
                    //fields: $scope.model,
                    file: i.file,
                }).progress(function (evt) {
                    i.progress = Math.min(100, parseInt(100.0 * evt.loaded / evt.total));
                    updateProgressbar();
                }).then(function successCallback(data) {
                    if (!data.data.success) {
                        var res = PostFileRecponse[data.data.data];
                        var resEn = PostFileRecponseEn[data.data.data];
                        notifyShow(IsRtl ? res : resEn, 0);
                    }
                    else i.done = true;
                    checkUploadsDone();
                }, function errorCallback(data) {
                    $scope.uploadErrors.push({ name: i.file.name, text: AlertSendFiles });
                    i.done = true;
                    checkUploadsDone();
                });
            });
        }
    });
    var updateProgressbar = function () {
        var sumProgress = 0;
        angular.forEach($scope.uploadItems, function (i) {
            sumProgress += i.progress;
        });
        $scope.archiveScope.uploadProgress = sumProgress / $scope.uploadItems.length;
        $('#progress-bar').css('width', $scope.archiveScope.uploadProgress + '%')
    };
    var checkUploadsDone = function () {
        var allDone = true;
        angular.forEach($scope.uploadItems, function (i) {
            allDone = allDone && i.done;
        });
        if (allDone) {
            $scope.uploadPanel = false;
            $scope.uploading = false;
            $scope.archiveScope.FileIndex = parseInt($scope.archiveScope.FileCount) + 50;
            $scope.archiveMan.load();
            uploadSelectedFiles = null;
            toaster.pop('success', '', UploadSuccessMessage);
        }
    };
});
