Dargah.controller('EquipmentCtrl', function ($scope, $http, $uibModal, $stateParams, $rootScope, $location, dynamicFieldGridServices, dxGridConfig2) {
    $rootScope.ActiveAddress = $location.path();
    $scope.RegisterFinishedAll = RegisterFinishedAll;
    $scope.loading = false;
    $scope.Additionalmethod = function () {
        $rootScope.$emit("CallAdditionalDataMethod", {});
    }
    $scope.contractorFields = contractorFields;
    $scope.load = function () {
        $scope.loading = true;
        $http.post('/additional/getEquipments?Type=' + $stateParams.Type).then(function successCallback(res) {
            $scope.Activity = res.data.data.Activity;
            $scope.CanEdit = res.data.data.CanEdit;
            $scope.IsShowRequestEditForm = res.data.data.IsShowRequestEditForm;
            $scope.RequiredFiledNotCompleted = res.data.data.RequiredFiledNotCompleted;
            RequiredFiledNotCompleted = res.data.data.RequiredFiledNotCompleted;
            $scope.loading = false;
        });
    };
    var gridInstanceMemeber = null;
    $scope.gridConfig = angular.extend({
        dataSource: dynamicFieldGridServices.newDataSource('/odata/contractorequipment?$orderby=InsertDate desc'),
        onInitialized: function (e) {
            gridInstanceMemeber = e.component;
        },
        onCellPrepared: (e) => {
            if (e.rowType === "data") {
                var index = RequiredFiledNotCompleted.find(x => x.EntityId == e.data.ID)
                if (index) {
                    var cell = index.Fields.find(x => x.Name == e.column.dataField || 'staticSource_' + x.ID == e.column.dataField)
                    if (cell)
                        e.cellElement.addClass("red-req");
                }
                //if (!$scope.CanEdit && e.column.type == 'buttons') {
                //    for (var item of e.cellElement.children("a").siblings()) {
                //        let classes = Array.from(item.classList);
                //        if (!classes.find(x => x == 'zmdi-download'))
                //            item.classList = ''
                //    }
                //}
                if (e.data.FileName == null && e.column.type == 'buttons')
                    e.cellElement.children("a").siblings(":first-child").removeClass();
            }
        },
        columns: dynamicFieldGridServices.addStatciFields([
            {
                caption: '#', width: 30,
                cellTemplate: function (cellElement, cellInfo) {
                    var rowNumber = cellInfo.rowIndex + 1;
                    if (gridInstanceMemeber != null)
                        rowNumber += gridInstanceMemeber.pageIndex() * gridInstanceMemeber.pageSize();
                    cellElement.text(rowNumber);
                }
            },
            { caption: IsRtl ? 'عنوان' : 'EquipmentName', dataField: 'Name', allowHeaderFiltering: false, visible: fieldListStatic.some(s => s.Name === "Name") },
            { caption: IsRtl ? 'تعداد' : 'Count', dataField: 'Count', width: 110, alignment: "center", allowHeaderFiltering: false, visible: fieldListStatic.some(s => s.Name === "Count") },
            { caption: IsRtl ? 'مالک' : 'Owner', dataField: 'Owner', width: 110, alignment: "center", allowHeaderFiltering: false, visible: fieldListStatic.some(s => s.Name === "Owner") },
            { caption: IsRtl ? 'توضیحات' : 'Description', dataField: 'Description', width: 150, alignment: "center", allowHeaderFiltering: false, visible: fieldListStatic.some(s => s.Name === "Description") },
            { caption: IsRtl ? 'وضعیت' : 'Status', width: 130, dataField: 'OK', lookup: { dataSource: JSON.parse(ListConfirmConditional), valueExpr: 'Key', displayExpr: 'Value' }, alignment: "center" },
            { caption: IsRtl ? 'تاریخ ثبت' : 'InsertDate', dataField: 'InsertDate', width: 160, alignment: "center", allowHeaderFiltering: false, allowFiltering: true },
            {
                type: "buttons", width: 150,
                fixed: true,
                fixedPosition: IsRtl ? "left" : "right",
                buttons: [
                    {
                        cssClass: "clickfeature",
                        icon: "zmdi zmdi-download",
                        hint: IsRtl ? "دانلود" : "Download",
                        onClick: function (e) {
                            window.open("/additional/DownloadDoc/?id=" + e.row.data.ID._value + '&fileName=' + e.row.data.FileName)
                        }
                    },
                    {
                        cssClass: "clickfeature",
                        icon: "edit",
                        hint: IsRtl ? "ویرایش" : "Edit",
                        onClick: async function (e) {
                            let data = await (await fetch('/additional/GetEntityById/' + e.row.data.ID + '?EntityType=contractorEquipment')).json()
                            var model = {
                                ID: e.row.data.ID,
                                Name: e.row.data.Name,
                                Owner: e.row.data.Owner,
                                Count: e.row.data.Count,
                                Description: e.row.data.Description,
                                Type: e.row.data.EquipmentType,
                                OK: e.row.data.OK == "Y" ? true : (e.row.data.OK == "N" ? false : "NULL"),
                                contractorFields: data.data.contractorFields,
                                FileName: e.row.data.FileName
                            };
                            $scope.edit(model);
                        }
                    },
                    {
                        cssClass: "clickfeature",
                        icon: "zmdi zmdi-delete",
                        hint: IsRtl ? "حذف" : "Delete",
                        onClick: function (e) {
                            $scope.delete(e.row.data)
                        }
                    }]
            }
        ], $scope.contractorFields)
    }, dxGridConfig2);
    $scope.edit = function (i) {
        if ($scope.IsShowRequestEditForm) {
            $uibModal.open({
                animation: true,
                templateUrl: '/ng-templates/RequestEdit.html',
                controller: 'RequestEditCtrl',
                size: 'md',
                resolve: {
                    model: { Comment: '' }
                }
            }).result.then(function (modalResult) {

            });
        }
        else {
            emptyMaker($scope.contractorFields)
            $uibModal.open({
                animation: true,
                templateUrl: '/templates/additional/edit-equipment.html',
                controller: 'editEquipmentModalCtrl',
                size: 'lg',
                resolve: {
                    model: function () {
                        return i ? i : { Type: $stateParams.Type, contractorFields: $scope.contractorFields };
                    },
                    Activity: () => $scope.Activity
                }
            }).result.then(function (r) {
                $scope.load();
                $scope.Additionalmethod();
            });
        }
    };

    $scope.delete = function (i) {
        if ($scope.IsShowRequestEditForm) {
            $uibModal.open({
                animation: true,
                templateUrl: '/ng-templates/RequestEdit.html',
                controller: 'RequestEditCtrl',
                size: 'md',
                resolve: {
                    model: { Comment: '' }
                }
            }).result.then(function (modalResult) {

            });
        }
        else {
            if (confirm('آیا از حذف این مورد اطمینان دارید؟')) {
                $http.post('/additional/deleteEquipment/' + i.ID).then(function successCallback(res) {
                    if (res.data.success) {
                        $scope.load();
                        $scope.Additionalmethod();
                    }
                    else {
                        toasty.error({ title: '', msg: 'مشکلی در اجرای عملیات بوجود آمده است' });
                    }
                }, function errorCallback() {
                    toasty.error({ title: '', msg: 'مشکلی در اجرای عملیات بوجود آمده است' });
                });
            }
        }
    };
    $scope.load();
});
