Dargah.controller('LoginController', function ($scope, $state, $http, $rootScope, $localStorage, $interval, vcRecaptchaService) {
    var onSuccess = function (response) {
        var errorDivs = document.getElementsByClassName("recaptcha-error");
        if (errorDivs.length) {
            errorDivs[0].className = "";
        }
        grecaptcha.ready(runCaptcha);
        setInterval(runCaptcha, 60000);
        var errorMsgs = document.getElementsByClassName("recaptcha-error-message");
        if (errorMsgs.length) {
            errorMsgs[0].parentNode.removeChild(errorMsgs[0]);
        }
        $('#frm').submit();
    };
    $scope.login = function () {
        event.preventDefault();
        if ($scope.UserName === '' || $scope.UserName === undefined) {
            $scope.Message = "نام کاربری را وارد نمایید";
            return;
        }

        if ($scope.Password === '' || $scope.Password === undefined) {
            $scope.Message = "رمز عبور را وارد نمایید.";
            return;
        }
        else {
            var rvt = angular.element('input[name="X-CSRF-Token"]').val();
            var httpConfig = { headers: { 'X-XSRF-Token': rvt } };
            $http.post('/login/Index', {
                username: $scope.UserName,
                password: $scope.Password,
                captcha: $('[name="g-recaptcha-response"]').val()
            }).then(function successCallback(res) {
                $scope.Message = res.data;
                if (res === 'ok') {
                    var now = new Date();
                    var exp = new Date(now.getTime() + 1800 * 1000);
                    document.cookie = 'ExpirationCookieTest=1; expires=' + exp.toUTCString();
                    localStorage.setItem("UserLogin", $scope.UserName);
                    $('.mfp-close').click();
                    $interval(function () {
                        window.location = "/";
                    }, 2000);
                }
                else {
                    runCaptcha = function (actionName) {
                        return new Promise((resolve, reject) => {
                            grecaptcha.ready(function () {
                                grecaptcha.execute(RecaptchaSiteKey, { action: 'BlazorContactForm' }).then(function (token) {
                                    resolve(token);
                                    $('[name="g-recaptcha-response"]').val(token);
                                });
                            });

                        });
                    };
                    grecaptcha.ready(runCaptcha);
                }
            });
        }
    };
});
Dargah.controller("ChangeMobileOrEmailcontroller", function ($scope, toaster, $state, $stateParams, $http, $window) {
    $scope.model = $stateParams.model;
    if ($stateParams.Message !== null)
        $scope.Message = $stateParams.Message;
    if ($stateParams.ShowOkMessage !== null)
        $scope.ShowOkMessage = $stateParams.ShowOkMessage;
    $scope.submit = function () {
        var rvt = angular.element('input[name="X-CSRF-Token"]').val();
        var httpConfig = { headers: { 'X-XSRF-Token': rvt } };
        var fileUpload = $("#File").get(0);
        var fileData = new FormData();
        if (fileUpload) {
            var files = fileUpload.files;
            for (var i = 0; i < files.length; i++) {
                fileData.append("File", files[i]);
            }
        }
        fileData.append("Code", $scope.model.Code);
        fileData.append("Name", $scope.model.Name);
        fileData.append("Post", $scope.model.Post);
        fileData.append("Description", $scope.model.Description);
        fileData.append("Mobile", $scope.model.Mobile);
        fileData.append("Email", $scope.model.Email);
        fileData.append("FileName", $scope.model.FileName ? $scope.model.FileName : '');
        fileData.append("Recaptcha", $scope.model.Recaptcha);

        fileData.append("CaptchaID", angular.element('input[name="CaptchaID"]').val());
        fileData.append("CaptchaValue", angular.element('input[name="CaptchaValue"]').val());

        $http.post('/Forget/SendChangeRequestForChangeMobileOrEmail', fileData,
            {
                transformRequest: angular.identity,
                headers: { 'Content-Type': undefined }
            },
            httpConfig)
            .then(function successCallback(res) {
                if (res.data === '')
                    $window.location.href = '/403.html';
                else if (res.data === 'NotFound' || res.data === 'Duplicate' || res.data === 'Email' || res.data === 'OneOfRequired') {
                    $state.go('ChangeMobileOrEmail', { Message: res.data, ShowOkMessage: false, model: $scope.model });
                    $scope.Message = res.data;
                    $scope.ShowOkMessage = false;
                } else if (res.data === 'OK') {
                    $state.go('ChangeMobileOrEmail', { Message: res.data, ShowOkMessage: true, model: $scope.model });
                    $scope.Message = res.data;
                    $scope.ShowOkMessage = true;

                }
                else {
                    $state.go('ChangeMobileOrEmail', { Message: res.data, model: $scope.model });
                }
            });
    };
});
Dargah.controller("forgetcontroller", function ($scope, toaster, $state, $stateParams, $http, $window) {
    $('.mfp-close').click();
    if ($stateParams.Message !== null) {
        $scope.Message = $stateParams.Message;
    }
    $scope.RecieveCode = IsRtl ? "دریافت کد" : "Recieve code"
    $scope.showPasswordSection = false;
    $scope.requestCodeBTNDisabled = false;
    $scope.requestCode = function () {
        if (!$scope.UserName || $scope.UserName == "" || $scope.UserName == " ") {
            IsRtl ? notifyShow("لطفا نام کاربری، ایمیل، یا شماره موبایل خود را وارد نمایید", 0) : notifyShow("Please enter your mobile number, email or username", 0)
            return false
        }
        var rvt = angular.element('input[name="X-CSRF-Token"]').val();
        var httpConfig = { headers: { 'X-XSRF-Token': rvt } };
        var count = 1;
        var fileData = new FormData();
        fileData.append("username", $scope.UserName);
        fileData.append("Recaptcha", $scope.Recaptcha);


        fileData.append("CaptchaID", angular.element('input[name="CaptchaID"]').val());
        fileData.append("CaptchaValue", angular.element('input[name="CaptchaValue"]').val());


        $scope.requestCodeBTNDisabled = true;
        $http.post('/Forget/ForgetPassword', fileData, { transformRequest: angular.identity, headers: { 'Content-Type': undefined } }, httpConfig).then(function successCallback(res) {
            if (res.data == 'recaptcha') {
                notifyShow("کد کپچا صحیح نمی باشد", 0)
            } else {
                if (res.data.Message) {
                    notifyShow(res.data.Message, 0)

                } else {

                    $scope.check = res.data.Check
                    $("#sendBTNID").addClass("cursorNotAllowed");
                    $scope.showPasswordSection = true;
                    $scope.RecieveCode = "ارسال مجدد";
                    var timer2 = '3:01';
                    var countDownFunc = setInterval(function () {
                        $scope.requestCodeBTNDisabled = true;
                        var timer = timer2.split(':');
                        var minutes = parseInt(timer[0], 10);
                        var seconds = parseInt(timer[1], 10);
                        --seconds;
                        minutes = (seconds < 0) ? --minutes : minutes;
                        if (minutes < 0) clearInterval(countDownFunc);
                        seconds = (seconds < 0) ? 59 : seconds;
                        seconds = (seconds < 10) ? '0' + seconds : seconds;
                        $('#countdown').html(minutes + ':' + seconds);
                        timer2 = minutes + ':' + seconds;
                        if (minutes == 0 && (seconds == 0 || seconds == "00")) {
                            $("#sendBTNID").removeClass("cursorNotAllowed");
                            $("#sendBTNID").addClass("cursorPointer");
                            $("#sendBTNID").removeAttr("disabled")
                            $scope.requestCodeBTNDisabled = false;
                            $('#countdown').html('۰۳:۰۰');
                            clearInterval(countDownFunc)
                        }
                    }, 1000);
                }
            }
        });
    };
    $scope.submit = function () {
        if (!$scope.ResetCode) {
            angular.element('#ResetCode').css("border", "1px solid red");
        } else {
            angular.element('#ResetCode').css("border", "");
        }
        if (!$scope.NewPass) {
            angular.element('#NewPass').css("border", "1px solid red");
        } else {
            angular.element('#NewPass').css("border", "");
        }
        if (!$scope.NewPass2) {
            angular.element('#NewPass2').css("border", "1px solid red");
        } else {
            angular.element('#NewPass2').css("border", "");
        }
        if (!$scope.resetPassword.$valid) {
            return;
        }
        if ($scope.NewPass !== $scope.NewPass2) {
            $scope.Message = 'failed'; 
            notifyShow("رمز عبور جدید و تکرار آن یکسان نیستند", 0);
            return;
        }
        var rvt = angular.element('input[name="X-CSRF-Token"]').val();
        var httpConfig = { headers: { 'X-XSRF-Token': rvt } };
        var fileData = new FormData();
        fileData.append("Check", $scope.check);
        fileData.append("ResetCode", $scope.ResetCode);
        fileData.append("NewPass", $('#NewPass').val());
        fileData.append("NewPass2", $('#NewPass2').val());
        $http.post('/resetpassword/ChangePass', fileData,
            {
                transformRequest: angular.identity,
                headers: { 'Content-Type': undefined }
            },
            httpConfig)
            .then(function successCallback(res) {
                if (res.data === "success") {
                    $scope.Message = "success";
                    notifyShow("کلمه عبور با موفقیت تغییر یافت.", 2);
                    setTimeout(() => {
                        location.href = "/login";
                    }, 3000);
                } else {
                    $scope.Message = res.data;
                    notifyShow("تغییر رمز عبور انجام نشد.", 0);
                }
            }, function errorCallback() {
                $scope.Message = "failed";
                notifyShow("خطا در ارتباط با سرور", 0);
            });
    };
});
Dargah.controller("changePasswordcontroller", function ($scope, toaster, $state, $http, $rootScope, $location) {
    $rootScope.ActiveAddress = $location.path();
    $scope.submit = function () {
        if (!$scope.changePassword.$valid) {
            return;
        }
        else {
            var rvt = angular.element('input[name="X-CSRF-Token"]').val();
            var httpConfig = { headers: { 'X-XSRF-Token': rvt } };
            var fileData = new FormData();
            fileData.append("Pass", $scope.Pass);
            fileData.append("NewPass", $scope.NewPass);
            fileData.append("NewPass2", $scope.NewPass2);
            $http.post('/changePassword/change', fileData,
                {
                    transformRequest: angular.identity,
                    headers: { 'Content-Type': undefined }
                },
                httpConfig)
                .then(function successCallback(res) {
                    if (!res.data.success) {
                        notifyShow(res.data.data, 0);
                    } else {
                        notifyShow("رمز عبور با موفقیت تغییر کرد. لطفا مجددا وارد شوید.", 2);
                        setTimeout(() => {
                            window.location = "/login/Signout";
                        }, 5000)
                    }
                });
        }
    };
});
Dargah.controller("RegisterCtrl", function ($scope, $state, $http, toaster, $stateParams, $location, FieldService, $rootScope, $parse) {
    $rootScope.ActiveAddress = $location.path();
    async function getDataSource() {
        if ((window.location.hash === '#/Register' || window.location.hash === '#/Register/Basic')) {
            let request = await fetchPost('/Register/Index?step=first');
            if (request.success) {
                $scope.actv = request.data.actv;
                $scope.defaultCountryID = defaultCountryID;
                $scope.Department = request.data.Department;
                $scope.DepartmentID = request.data.DepartmentID;
                $scope.type = request.data.type;
                $scope.IsRtl = request.data.IsRtl;
                $scope.Fields = request.data.Fields;
                $scope.viewerMan = FieldService($scope.Fields, $scope.tableID, $scope);
                $scope.viewerMan.TagBoxes($parse).map((item) => { $scope["tagBoxFormField_" + item.ID] = item });
                $scope.RegisterTagBox = {
                    customTemplate: {
                        dataSource: $scope.actv,
                        displayExpr: 'Value',
                        valueExpr: 'Key',
                        placeholder: IsRtl ? 'نوع فعالیت (با امکان انتخاب چندین مورد)' : 'Select the type of activity ... ',
                        rtlEnabled: IsRtl,
                        onValueChanged(e) {
                            if (e.value.length > 0) {
                                $('input[name="BasicActivity"]').val(e.value)
                                $('label[id="BasicActivity-error"]').css("display", "none")
                            } else if (e.value.length == 0) {
                                $('input[name="BasicActivity"]').val(null)
                            }
                        }
                    },
                };
                $rootScope.loading = true;
                $scope.$apply()
            };
        };
    };
    getDataSource();
    $(document).ready(async function () {
        if (window.location.hash === '#/Register/Basic') {
            let request = await fetchPost('/Register/Index?step=second');
            if (request.success) {
                $scope.provinces = request.data.Provinces;
                $scope.cities = request.data.Cities;
                $scope.Banks = request.data.Banks;
                $scope.Countries = request.data.Countries;
                $scope.CountryID = request.data.CountryID;
                $scope.defaultCountryID = defaultCountryID;
                $scope.IsRtl = request.data.IsRtl;
                $scope.Security = request.data.Security;
                $scope.Basic.CountryID = $scope.CountryID;
                $scope.selectedCountry = $("select[name='CountryID']").val() == '' || $("select[name='CountryID']").val() == null || $("select[name='CountryID']").val() == undefined || $("select[name='CountryID']").val() == "?" ? $scope.Basic.CountryID : $("select[name='CountryID']").val();
                $rootScope.loaded = true;
            }
        }
    });
    $scope.changeCountryForMobileNumber = () => {
        $scope.selectedCountry = $("select[name='CountryID']").val();
        $scope.selectedCountry = $scope.selectedCountry.split(":")[1]
    }
    $scope.Basic = { Activity: '', Type: 'company', CountryID: $scope.CountryID, EstablishmentDate: null, DepartmentID: $scope.DepartmentID };
    $("#alertblacklist").addClass("d-none");
    $("#alertCodemeli").addClass("d-none");
    $scope.RegUpload = function () {
        $state.go('RegUpload');
    }
    $scope.CheckNationalCode = function CheckNationalCode() {
        if ($('#NationalCode').val() == '') {
            return false;
        }
        $http.post('/register/checknationalcode?national=' + $('#NationalCode').val()).then(function successCallback(res) {
            if (res.data.data === true) {
                $("#alertblacklist").removeClass("d-none");
                $scope.alertblacklist = true;
                return false;
            }
            else {
                $("#alertblacklist").addClass("d-none");
                $scope.alertblacklist = false;
                return false;
            }
        });
    };
    $scope.CheckCeoNationalCode = function CheckCeoNationalCode() {
        if ($('#CeoNationalCode').val() == '') {
            return false;
        }
        $http.post('/register/checknationalcode?national=' + $('#CeoNationalCode').val()).then(function successCallback(res) {
            if (res.data.data === true) {
                $("#alertblacklist").removeClass("d-none");
                $scope.alertblacklist = true;
                return false;
            }
            else {
                $("#alertblacklist").addClass("d-none");
                $scope.alertblacklist = false;
                return false;
            }
        });
    };

    $scope.step1 = function () {
        $state.go('Basic', {});
    };
    $scope.CheckConditions = function () {
        var list = [];
        $scope.viewerMan = FieldService($scope.Fields, $scope.Basic.ID);
        list = $scope.viewerMan.data();
        $scope.Basic.JsonFields = JSON.stringify(list);
        $http.post('/Register/CheckCondition', { Activity: JSON.stringify($scope.Basic.Activity), Type: $scope.Basic.Type, JsonFields: $scope.Basic.JsonFields })
            .then(function successCallback(res) {
                $scope.Fields = res.data.data;
            });
    }
    function checkCodeMeliCompany(code) {
        if (!code) return false;
        var L = code.length;
        if (L < 11 || parseInt(code, 10) == 0) return false;
        if (parseInt(code.substr(3, 6), 10) == 0) return false;
        var c = parseInt(code.substr(10, 1), 10);
        var d = parseInt(code.substr(9, 1), 10) + 2;
        var z = new Array(29, 27, 23, 19, 17);
        var s = 0;
        for (var i = 0; i < 10; i++)
            s += (d + parseInt(code.substr(i, 1), 10)) * z[i % 5];
        s = s % 11;
        if (s == 10) s = 0;
        return (c == s);
    }
    function checkMelliCode(meli_code) {
        if (!meli_code) return false;
        if (meli_code.length == 10) {
            if (meli_code == '1111111111' || meli_code == '2222222222' || meli_code == '3333333333' || meli_code == '4444444444' || meli_code == '5555555555' || meli_code == '6666666666' || meli_code == '7777777777' || meli_code == '8888888888' || meli_code == '9999999999') {
                return false;
            } else {
                c = parseInt(meli_code.charAt(9));
                n = parseInt(meli_code.charAt(0)) * 10 + parseInt(meli_code.charAt(1)) * 9 + parseInt(meli_code.charAt(2)) * 8 + parseInt(meli_code.charAt(3)) * 7 + parseInt(meli_code.charAt(4)) * 6 + parseInt(meli_code.charAt(5)) * 5 + parseInt(meli_code.charAt(6)) * 4 + parseInt(meli_code.charAt(7)) * 3 + parseInt(meli_code.charAt(8)) * 2;
                r = n - parseInt(n / 11) * 11;
                if ((r == 0 && r == c) || (r == 1 && c == 1) || (r > 1 && c == 11 - r)) {
                    return true;
                }
                else {
                    return false;
                }
            }
        }
    }
    function _validateCodeMeli() {
        var _country = $("#CountryID").val().replace('number:', '');
        var _code = $("#NationalCode").val();
        var _type = $("#Type").val().replace('string:', '');

        if (defaultCountryID == _country)
        {
            if ($("#NationalCode").attr('required') == undefined &&( _code == undefined || _code== ''))
                return true;
            var _ceoCode = $("#CeoNationalCode").val();
            if (_type != "person") {
                if (checkMelliCode(_ceoCode) != true) {
                    $("#CeoNationalCode").addClass('has-error');
                }

            }
            if (_type == "person") { //کد ملی
                if (checkMelliCode(_code) != true) {
                    $("#NationalCode").addClass('has-error');
                    return false;
                }
                else {
                    $("#alertCodemeli").addClass("d-none");
                    $("#NationalCode").removeClass('has-error');
                    return true;
                }
            }
            else if (_type == "company" || _type == "publicequity" || _type == "limitedtask") {
                if (checkCodeMeliCompany(_code) != true) {
                    $("#alertCodemeli").removeClass("d-none");
                    $("#NationalCode").addClass('has-error');
                    return false;
                }
                else {
                    $("#alertCodemeli").addClass("d-none");
                    $("#NationalCode").removeClass('has-error');
                    return true;
                }
            }
            else {
                $("#alertCodemeli").addClass("d-none");
                $("#NationalCode").removeClass('has-error');
                return true;
            }
        }
        else {
            return true;
        }
    };
    $scope.CheckValidPass = function () {
        var validPass = true;
        if ($scope.Basic.Password) {
            if (!(/[!@@#$%^&*]/).test($scope.Basic.Password) && $scope.Security.PasswordAcceptSpecialCharacter == 'Y') {
                notifyShow("رمز عبور وارد شده باید شامل کاراکترهای خاص باشد", 3)
                validPass = false;
            }
            if (!(/[0-9]/).test($scope.Basic.Password) && $scope.Security.PasswordAcceptNumber == 'Y') {
                notifyShow("رمز عبور وارد شده باید شامل اعداد باشد", 3)
                validPass = false;
            }
            if ((!(/[a-z]/).test($scope.Basic.Password) && $scope.Security.PasswordAcceptAlpha == 'Y') || (!(/[A-Z]/).test($scope.Basic.Password) && $scope.Security.PasswordAcceptAlpha == 'Y')) {
                notifyShow("رمز عبور وارد شده باید شامل حروف بزرگ و کوچک انگلیسی باشد", 3)
                validPass = false;
            }
            if ($scope.Basic.Password.length < parseInt($scope.Security.PasswordMinLength)) {
                if (IsRtl) {
                    notifyShow("طول رمز عبور وارد شده حداقل " + $scope.Security.PasswordMinLength + " کاراکتر می باشد", 3)
                } else {
                    notifyShow("Minimum length of password is " + $scope.Security.PasswordMinLength, 3)
                }
                validPass = false;
            }
            if ($scope.Basic.Password.length > parseInt($scope.Security.PasswordMaxLength)) {
                if (IsRtl) {
                    notifyShow("طول رمز عبور وارد شده حداکثر " + $scope.Security.PasswordMaxLength + " کاراکتر نمی باشد", 3)
                }
                else {
                    notifyShow("Maximum length of password is " + $scope.Security.PasswordMaxLength, 3)
                }
                validPass = false;
            }
        };
        return validPass;
    };
    $scope.CheckRepeatValidPass = function () {
        var validPass = true;
        if ($scope.Basic.Password) {
            if ($scope.Basic.Password2 !== $scope.Basic.Password) {
                if (IsRtl) {
                    notifyShow("رمز عبور با تکرار کلمه عبور یکسان نمی باشد", 3)
                }
                else {
                    notifyShow("The password is not the same as repeating the password", 3)
                }
                validPass = false;
            }
        }
        return validPass;
    };

    $scope.checkEmailValidation = function () {
        const email = encodeURIComponent($scope.Basic.Email);
        const csrfToken = document.querySelector("input[name='X-CSRF-Token']").value;

        return fetch(`/register/checkemailValidation?email=${email}`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': csrfToken
            },
        })
            .then(response => response.text())
            .then(data => {
                return data.toLowerCase() == 'true';
            })
            .catch((err) => {
                return false;
            });
    };
  
    $scope.SaveBasic = function () {
        if ($scope.CheckValidPass() == false || $scope.CheckRepeatValidPass() == false) {
            return false;
        }
        console.log($scope.registerForm)
        $scope.checkEmailValidation().then(function (isValidEmail) {
            if (!isValidEmail) {
                notifyShow(IsRtl ? "ایمیل وارد شده قبلاً ثبت شده است یا معتبر نیست" :"The entered email is invalid.", 0);
                return false;
            }
            if ($scope.registerForm.$valid && _validateCodeMeli()) {
                if (confirm(Alertconfirm)) {
                    var rvt = angular.element('input[name="X-CSRF-Token"]').val();
                    var httpConfig = { headers: { 'X-XSRF-Token': rvt } };
                    var fileData = new FormData();
                    $scope.data = [];
                    angular.forEach($scope.Fields, function (j) {
                        $scope.data.push({ ID: j.ID, Value: j.Value });
                    })
                    $scope.viewerMan = FieldService($scope.Fields, $scope.Basic.ID);
                    if ($scope.viewerMan.valid() === false) {
                        $scope.disable = false;
                        return false;
                    }
                    if ($('#ShabaNumber').val()) {
                        if ($scope.Basic.ShabaNumber.length < 24 && $scope.Basic.ShabaNumber != "" && $scope.Basic.ShabaNumber != undefined) {
                            return false;
                        }
                    }
                    var list = $scope.viewerMan.data();
                    $scope.Basic.JsonFields = JSON.stringify(list);
                    fileData.append("Name", $scope.Basic.Name ? $scope.Basic.Name : '');
                    fileData.append("NameEN", $scope.Basic.NameEN ? $scope.Basic.NameEN : '');
                    fileData.append("Type", $scope.Basic.Type ? $scope.Basic.Type : '');
                    fileData.append("Activity", $scope.Basic.Activity ? $scope.Basic.Activity : '');
                    fileData.append("NationalCode", $scope.Basic.NationalCode ? $scope.Basic.NationalCode : '');
                    if (IsRtl) {
                        fileData.append("ProvinceID", $scope.Basic.ProvinceID ? $scope.Basic.ProvinceID : '');
                        fileData.append("CityID", $scope.Basic.CityID ? $scope.Basic.CityID : '');
                    }
                    fileData.append("BankID", $scope.Basic.BankID ? $scope.Basic.BankID : '');
                    fileData.append("DUNS", $scope.Basic.DUNS ? $scope.Basic.DUNS : '');
                    fileData.append("ShomareSabt", $scope.Basic.ShomareSabt ? $scope.Basic.ShomareSabt : '');
                    if ($scope.Basic.FoundationDate && $scope.Basic.FoundationDate.length !== 0) {
                        fileData.append("FoundationDate", cultureInfo === "fa-IR" ? $scope.Basic.FoundationDate : $scope.Basic.FoundationDate);
                    }
                    fileData.append("EconomicCode", $scope.Basic.EconomicCode ? $scope.Basic.EconomicCode : '');
                    fileData.append("CeoName", $scope.Basic.CeoName ? $scope.Basic.CeoName : '');
                    fileData.append("CeoNationalCode", $scope.Basic.CeoNationalCode ? $scope.Basic.CeoNationalCode : '');
                    fileData.append("CeoMobile", $scope.Basic.CeoMobile ? $scope.Basic.CeoMobile : '');
                    fileData.append("Mobile", $scope.Basic.Mobile ? $scope.Basic.Mobile : '');
                    fileData.append("Phone", $scope.Basic.Phone ? $scope.Basic.Phone : '');
                    fileData.append("PrePhone", $scope.Basic.PrePhone ? $scope.Basic.PrePhone : '');
                    fileData.append("Fax", $scope.Basic.Fax ? $scope.Basic.Fax : '');
                    fileData.append("PostalCode", $scope.Basic.PostalCode ? $scope.Basic.PostalCode : '');
                    fileData.append("Email", $scope.Basic.Email ? $scope.Basic.Email : '');
                    fileData.append("Website", $scope.Basic.Website ? $scope.Basic.Website : '');
                    fileData.append("Address", $scope.Basic.Address ? $scope.Basic.Address : '');
                    fileData.append("Password", $scope.Basic.Password ? $scope.Basic.Password : '');
                    fileData.append("Password2", $scope.Basic.Password2 ? $scope.Basic.Password2 : '');
                    fileData.append("RegistrationAddress", $scope.Basic.RegistrationAddress ? $scope.Basic.RegistrationAddress : '');
                    fileData.append("InsuranceBranch", $scope.Basic.InsuranceBranch ? $scope.Basic.InsuranceBranch : '');
                    fileData.append("BankAccount", $scope.Basic.BankAccount ? $scope.Basic.BankAccount : '');
                    fileData.append("BranchAccount", $scope.Basic.BranchAccount ? $scope.Basic.BranchAccount : '');
                    fileData.append("ShabaNumber", $scope.Basic.ShabaNumber ? $scope.Basic.ShabaNumber : '');
                    fileData.append("CountryID", $scope.Basic.CountryID ? $scope.Basic.CountryID : '');
                    fileData.append("DepartmentID", $scope.Basic.DepartmentID ? $scope.Basic.DepartmentID : '');
                    fileData.append("Recaptcha", $scope.Basic.Recaptcha);


                    fileData.append("CaptchaID", angular.element('input[name="CaptchaID"]').val());
                    fileData.append("CaptchaValue", angular.element('input[name="CaptchaValue"]').val());


                    fileData.append("JsonFields", $scope.Basic.JsonFields);
                    $http.post('/Register/Basic', fileData, { transformRequest: angular.identity, headers: { 'Content-Type': undefined } }, httpConfig).then(function successCallback(res) {
                        if (res.data.Error === null) {
                            if (res.data.RegisterFinished) {
                                window.location.href = "/login?s=1";
                            } else {
                                window.location.href = "/login?s=1&a=1";
                            }
                        }
                        else if (res.data.Error !== null) {
                            notifyShow(res.data.Error, 0)
                            return false;
                        }
                    });
                }
                return false;
            }
        });
        };
});
Dargah.controller('fieldregisterCtrl', function ($scope, $http, $uibModal, $state, toaster, $localStorage, $filter) {
    $scope.$storage = $localStorage.$default({
        fields: null,
        registerbase: null,
        categories: null
    });
    $scope.step1 = function () {
        $scope.$storage.registerbase = null;
        $scope.$storage.formfields = null;
        $scope.$storage.fields = null;
        $scope.$storage.categories = null;
        $scope.$storage = null;
        $http.post('/Register/Index?start=1').then(function successCallback(res) {
            $state.go('Basic', {
                actv: res.data.data.actv,
                IsRtl: res.data.data.IsRtl,
                type: res.data.data.type,
                Provinces: res.data.data.Provinces,
                Cities: res.data.data.Cities,
                Fields: res.data.data.Fields,
                Banks: res.data.data.Banks
            });
        });
    };
    $scope.list = [];
    $scope.load = function () {
        var activity = $scope.$storage.registerbase.Activity;
        $http.post('/register/getFields?Activity=' + activity).then(function successCallback(res) {
            $scope.loading = true;
            $scope.list = $scope.$storage.fields ? $scope.$storage.fields : [];
            $scope.BaseContractorFields = res.data.data.BaseContractorFields;
            $scope.contractorFields = res.data.data.contractorFields;
            $scope.itemsbase = res.data.data.BaseContractorCategory;
            $scope.CategoryType = res.data.data.CategoryType;
            $scope.CanEdit = res.data.data.CanEdit;
            $scope.IsShowRequestEditForm = res.data.data.IsShowRequestEditForm;
            $scope.loading = false;
        });
    };
    $scope.Basecategories = function () {
        $scope.loading = true;
        $scope.listCategories = [];
        $http.post('/register/GetBaseCategories').then(function successCallback(res) {
            $scope.itemsbase = res.data.data.BaseContractorCategory;
            $scope.CategoryType = res.data.data.CategoryType;
            $scope.CategorycontractorFields = res.data.data.contractorFields;
            $scope.loading = false;
        }, function errorCallback(res) {
            toaster.pop("error", ErrorMessage, AlertErrorFetching);
        });
    };
    $scope.edit = function (i, index) {
        if ($scope.IsShowRequestEditForm) {
            $uibModal.open({
                animation: true,
                templateUrl: '/ng-templates/RequestEdit.html',
                controller: 'RequestEditCtrl',
                size: 'md',
                resolve: {
                    model: { Comment: '' }
                }
            }).result.then(function (modalResult) {

            });
        }
        else {
            $uibModal.open({
                animation: true,
                templateUrl: '/templates/additional/edit-fields.html',
                controller: 'regeditFieldsModalCtrl',
                size: 'lg',
                resolve: {
                    model: function () { return i; },
                    BaseContractorFields: () => $scope.BaseContractorFields
                }
            }).result.then(function (res) {
                if (index === null) {
                    if ($filter('filter')($scope.list, { ContractorFieldID: res.model.ContractorFieldID }).length > 0)
                        toaster.pop("error", ErrorMessage, 'فیلد وارد شده تکراری می باشد');
                    else
                        $scope.list.push(res.model);
                }
                else
                    $scope.list[index] = res.model;
                $scope.$storage.fields = $scope.list;
            });
        }
    };
    $scope.delete = function (index) {
        if ($scope.IsShowRequestEditForm) {
            $uibModal.open({
                animation: true,
                templateUrl: '/ng-templates/RequestEdit.html',
                controller: 'RequestEditCtrl',
                size: 'md',
                resolve: {
                    model: { Comment: '' }
                }
            }).result.then(function (modalResult) {

            });
        }
        else {
            if (confirm(AlertRemove)) {
                $scope.list.splice(index, 1);
                $scope.$storage.fields = $scope.list;
            }
        }
    };
    $scope.load();
    $scope.RegUpload = function () {
        $state.go('RegUpload');
    }
    $scope.selectCategory = function () {
   
        var CategoryRoot = null;
        $uibModal.open({
            animation: true,
            templateUrl: '/ng-templates/select-typeAndCategory.html',
            controller: 'selectTypeAndCategoryRegModalCtrl',
            size: 'lg',
            resolve: {
                CategoryRoot: () => CategoryRoot,
                CategoryType: () => $scope.CategoryType,
                Activity: () => $scope.$storage.registerbase.Activity,
            }
        }).result.then(function (res) {
            angular.forEach(res, function (j) {
                if ($filter('filter')($scope.listCategories, { BaseCategoryID: j.BaseCategoryID }).length > 0)
                    toaster.pop("error", ErrorMessage, 'رسته وارد شده تکراری می باشد');
                else $scope.listCategories.push(j);
                $scope.$storage.categories = $scope.listCategories;
            })
        });
    };
    $scope.allcategories = function () {
        $scope.listCategories = $scope.$storage.categories ? $scope.$storage.categories : [];
    };

    $scope.removeCategory = function (index) {
        if (confirm(AlertRemove)) {
            $scope.listCategories.splice(index, 1);
        }
    };
    $scope.Prev = function () {
        $http.post('/Register/Index')
            .then(function successCallback(res) {
                //res.data.data.Cities.push({ ID: '', Name: 'انتخاب ' });  
                $state.go('Basic', { actv: res.data.data.actv, type: res.data.data.type, Provinces: res.data.data.Provinces, Cities: res.data.data.Cities, Fields: res.data.data.Fields, Banks: res.data.data.Banks });
            });
    }
    $scope.allcategories();
});
Dargah.controller('regeditFieldsModalCtrl', function ($scope, $http, $uibModalInstance, toaster, model, BaseContractorFields, FieldService, $filter) {
    $scope.model = model;
    //$http.post('/register/GetBaseField').success(function (res) {
    $scope.BaseFields = BaseContractorFields;
    angular.forEach($scope.model.contractorFields, function (j) {
        var val = j.Value;
        if (val !== null && j.DataType === "multiselect") {
            if (val.includes(','))
                j.Value = val.split(',');
            else j.Value = JSON.parse('["' + val + '"]');
        }
    })
    //}).error(function (res) {
    //    toaster.pop('error', "خطا", "مشکلی در انجام عملیات بوجود آمده است");

    //})
    $scope.ok = function () {
        $scope.model.Name = $filter('filter')($scope.BaseFields, { ID: model.ContractorFieldID })[0].Name;
        var list = [];
        $scope.viewerMan = FieldService($scope.model.contractorFields, $scope.model.ID);
        if ($scope.viewerMan.valid() === false) {
            $scope.disable = false;
            return false;
        }
        if (!$scope.EditFields.$$element[0].Valid) {
            $scope.disable = false;
            return;
        }
        list = $scope.viewerMan.data();
        $scope.model.JsonFields = JSON.stringify(list);
        var rvt = angular.element('input[name="X-CSRF-Token"]').val();
        var httpConfig = { headers: { 'X-XSRF-Token': rvt } };
        var fileUpload = $("#File").get(0);
        var files = fileUpload.files;
        //if ($scope.model.ContractorFieldID === '' || $scope.model.ContractorFieldID === null) {
        //    toaster.error({ title: '', msg: 'لطفا عنوان را وارد نمایید' });
        //    return;
        //}
        //if ((files == '' || files == null) && Id != null) {
        //    toaster.error({ title: '', msg: 'لطفا فایل را انتخاب نمایید' });
        //    return;
        //}

        // Create FormData object
        var fileData = new FormData();
        // Looping over all files and add it to FormData object
        for (var i = 0; i < files.length; i++) {
            fileData.append("File", files[i]);
        }
        for (var j = 0; j < $scope.model.contractorFields.length; j++) {
            if ($scope.model.contractorFields[j].DataType === 'file')
                fileData.append("contractorFile" + $scope.model.contractorFields[j].ID, $("#myFile" + $scope.model.contractorFields[j].ID).get(0).files[0]);
        }
        fileData.append("ID", $scope.model.ID);
        fileData.append("ContractorFieldID", $scope.model.ContractorFieldID);
        fileData.append("Rotbe", $scope.model.Rotbe);
        fileData.append("File", $scope.model.File ? $scope.model.File : '');
        fileData.append("Description", $scope.model.Description ? $scope.model.Description : '');
        fileData.append("JsonFields", $scope.model.JsonFields ? $scope.model.JsonFields : '');
        // Adding one more key to FormData object
        $http.post('/register/postFields', fileData,
            {
                transformRequest: angular.identity,
                headers: { 'Content-Type': undefined }
            },
            httpConfig)
            .then(function successCallback(result) {
                if (result.data.success) {
                    if (result.data.data.File !== null)
                        $scope.model.File = result.data.data.File;
                    toaster.pop('success', "", success);
                    $uibModalInstance.close({ model: $scope.model });
                }
                else
                    toaster.pop('error', '', 'اطلاعات ارسالی تکراری یا نامعتبر است');
            }, function errorCallback(err) {
                toaster.pop('error', '', '');
            });
    };
    $scope.cancel = function () {
        $uibModalInstance.dismiss('cancel');
    };
});
