Dargah.controller('TypeCtrl', function ($scope, $http, $uibModal, toaster, $filter, $rootScope, $stateParams, $location, dxGridConfig2, dynamicFieldGridServices) {
    $rootScope.ActiveAddress = $location.path();
    $scope.RegisterFinishedAll = RegisterFinishedAll;
    $scope.loading = false;
    $scope.limited = false;
    $scope.Additionalmethod = function () {
        $rootScope.$emit("CallAdditionalDataMethod", {});
    }
    $scope.load = async function () {
        $scope.loading = true;
        $scope.rtl = true;
        $http.post('/Additional/GetCategories').then(function successCallback(res) {
            $scope.itemsbase = res.data.data.Base_Categorys;
            $scope.CategoryType = res.data.data.CategoryType;
            $scope.Activity = res.data.data.ActivityList;
            $scope.actv = res.data.data.actv;
            $scope.contractorFields = res.data.data.contractorFields;
            $scope.limited = res.data.data.Limited;
            $scope.rtl = res.data.data.rtl;
            $scope.CanEdit = res.data.data.CanEdit;

            $scope.IsShowRequestEditForm = res.data.data.IsShowRequestEditForm;
            $scope.loading = false;
        }, function errorCallback(res) {
            toaster.pop("error", ErrorMessage, AlertErrorFetching);
        });
    };
    $scope.load();
    $scope.selectCategory = function (section) {
        if ($scope.IsShowRequestEditForm) {
            $uibModal.open({
                animation: true,
                templateUrl: '/ng-templates/RequestEdit.html',
                controller: 'RequestEditCtrl',
                size: 'md',
                resolve: {
                    model: { Comment: '' }
                }
            }).result.then(function (modalResult) { });
        }
        else {
            var CategoryRoot = null;
            $uibModal.open({
                animation: true,
                templateUrl: '/ng-templates/select-typeAndCategory.html',
                controller: 'selectTypeAndCategoryModalCtrl',
                size: 'lg',
                resolve: {
                    model: function () { return section ? section : { contractorFields: $scope.contractorFields, Activity: $scope.Activity } },
                    CategoryRoot: () => CategoryRoot,
                    CategoryType: () => $scope.CategoryType,
                    rtl: () => $scope.rtl,
                    countCategory: () => gridInstance.getDataSource()._items.filter(item => item.isDeleted !== true).length,
                    CategoryLimit: () => CountContractorCaregory
                }
            }).result.then(function (res) {
                $scope.load();
                $scope.Additionalmethod();
            });
        }
    };
    var gridInstance = null;
    var contractorCategoryGradeHistoryInstance = null;
    $scope.gridCategories = angular.extend({
        onInitialized: function (e) {
            gridInstance = e.component;
        },
        dataSource: {
            store:
                dynamicFieldGridServices.newDataSource(`/odata/contractorcategories`), sort: { selector: 'InsertDate', desc:true }
        },

        onCellPrepared: (e) => {
            if (e.rowType === "data") {
                var index = RequiredFiledNotCompleted.find(x => x.EntityId == e.data.ID)
                if (index) {
                    var cell = index.Fields.find(x => x.Name == e.column.dataField || 'staticSource_' + x.ID == e.column.dataField)
                    if (cell)
                        e.cellElement.addClass("red-req");
                }
            }
        },
        columns: [
            { caption: IsRtl ? 'عنوان' : 'Service / Product Description', dataField: IsRtl ? 'CategoryName' : 'CategoryEnName', allowHeaderFiltering: false },
            {
                caption: 'نوع فعالیت', dataField: "Contractor_Category_Activity", width: 130, alignment: "center",
                allowHeaderFiltering: false, allowFiltering: true, allowSorting: false,
            },
            { alignment: "center", caption: 'گرید', dataField: 'BaseGradeID', width: 110, lookup: { dataSource: gradeListDataSource, displayExpr: "Value", valueExpr: "Key" } },
            {
                caption: 'وضعیت', dataField: "Active", width: 130, alignment: "center",
                allowHeaderFiltering: false, allowFiltering: true, allowSorting: false,
                lookup: { dataSource: listConfirmConditional, displayExpr: "Value", valueExpr: "Key" },
                cellTemplate: (cellElement, cellInfo) => {
                    if (cellInfo.data.Active == 'Y') {
                        cellElement.text(cellInfo.text);
                        cellElement.css('color', 'green');
                    } else if (cellInfo.data.Active == 'N') {
                        cellElement.text(cellInfo.text);
                        cellElement.css('color', 'red');
                    } else if (cellInfo.data.Active == '0') {
                        cellElement.text(cellInfo.text);
                        cellElement.css('color', '#f58a18');
                    } else if (cellInfo.data.Active == 'C') {
                        cellElement.text(cellInfo.text);
                        cellElement.css('color', 'yellowgreen');
                    } else {
                        cellElement.text(cellInfo.text);
                    }
                }
            },
            { caption: IsRtl ? 'توضیحات' : 'Remarks', dataField: 'Description', alignment: "center", width: 190, allowHeaderFiltering: false, visible: fieldListStatic.some(s => s.Name === "Description") },
            { caption: IsRtl ? 'تاریخ ثبت' : 'InsertDate', dataField: 'InsertDate', width: 160, alignment: "center", allowHeaderFiltering: false, allowFiltering: true },
            {
                type: "buttons", width: 110,
                buttons: [
                    {
                        name: '', hint: 'تاریخچه تغییرات گرید', cssClass: "clickfeature dx-icon  fa fa-history dx-link-icon", text: "",
                        onClick(e) {
                            if (!e.row.isExpanded) {
                                gridInstance.expandRow(e.row.data.ID);
                            } else if (e.row.isExpanded) {
                                gridInstance.collapseAll(-1)
                                e.row.isExpanded = false
                            }
                        }
                    },
                    {
                        name: 'delete', hint: 'حذف', cssClass: "clickfeature dx-icon zmdi zmdi-delete dx-link-icon", text: "",
                        visible: function (e) { return !(e.row.data.Active == "Y" || e.row.data.Active == "C") && $scope.CanEdit },
                        onClick: function (e) {
                            $scope.delete(e.row.data)
                        }
                    },
                ]
            }
        ],
        editing: { mode: 'row', allowUpdating: true, allowDeleting: true, confirmDelete: false, allowAdding: true, startEditAction: 'dblClick' },
        masterDetail: { enabled: true, template: "detail" },
    }, dxGridConfig2);

    $scope.contractorCategoryGradeHistory = function (data) {
        $scope.rowData = data;
        return angular.extend({
            onInitialized(e) {
                contractorCategoryGradeHistoryInstance = e.component;
            },
            dataSource: { store: { type: 'odata', url: `/odata/ContractorCategoryGradeHistory?ContractorCategoryActivityID=${$scope.rowData.data.ID}`, version: 4 }, sort: { selector: "ScoreDate", desc: true } },
            toolbar: { items: [] },
            columns: [
                { dataField: "TypeID", caption: "نوع ارزیابی", minWidth: 120, lookup: { dataSource: evaluationTypeID, valueExpr: 'Key', displayExpr: 'Value' } },
                { alignment: "center", caption: 'گرید قبلی', dataField: 'OldBaseGradeID', width: 90, allowHeaderFiltering: false, allowFiltering: false, lookup: { dataSource: gradeListDataSource, displayExpr: "Value", valueExpr: "Key" } },
                { alignment: "center", caption: 'گرید', dataField: 'BaseGradeID', width: 110, lookup: { dataSource: gradeListDataSource, displayExpr: "Value", valueExpr: "Key" } },
                {
                    alignment: "center", caption: 'امتیاز قبلی', dataField: 'OldScore', width: 90, allowHeaderFiltering: false, allowFiltering: false,
                    cellTemplate(cellElement, cellInfo) {
                        if (cellInfo.row.data.OldScore) {
                            cellElement.text(cellInfo.row.data.OldScore.toFixed(2))
                        }
                    }
                },
                {
                    alignment: "center", caption: 'امتیاز', dataField: 'Score', width: 90, allowHeaderFiltering: false, allowFiltering: false,
                    cellTemplate(cellElement, cellInfo) {
                        if (cellInfo.row.data.Score) {
                            cellElement.text(cellInfo.row.data.Score.toFixed(2))
                        }
                    }
                },
                { alignment: "center", caption: 'تاریخ اعمال امتیاز قبلی', dataField: 'OldScoreDate', width: 160, allowHeaderFiltering: false, allowFiltering: false },
                { alignment: "center", caption: 'تاریخ اعمال امتیاز', dataField: 'ScoreDate', width: 180, allowHeaderFiltering: false, allowFiltering: false },
            ]
        }, dxGridConfig2, {
            filterRow: { visible: false },
            allowColumnReordering: false,
            pager: {
                visible: false,
                showPageSizeSelector: false,
                showInfo: true,
                showNavigationButtons: false,
            },
            scrolling: { mode: 'virtual' },
            columnAutoWidth: true,
        });
    };
    $scope.close = function () {
        gridInstance.collapseAll(-1)
    };
    $scope.edit = function (model) {
        if ($scope.IsShowRequestEditForm) {
            $uibModal.open({
                animation: true,
                templateUrl: '/ng-templates/RequestEdit.html',
                controller: 'RequestEditCtrl',
                size: 'md',
                resolve: {
                    model: { Comment: '' }
                }
            }).result.then(function (modalResult) { });
        }
        else {
            model.ActivityList = $scope.Activity;
            $uibModal.open({
                animation: true,
                templateUrl: '/templates/edit.html',
                controller: 'editCategoryCtrl',
                size: 'lg',
                resolve: {
                    //model: function () { return model; },
                    model: function () { return model ? model : { Type: $stateParams.Type, contractorFields: $scope.contractorFields, ActivityList: $scope.Activity } },
                    itemsbase: function () { return $scope.itemsbase; },
                    CategoryType: function () { return $scope.CategoryType; },
                    Activity: () => $scope.Activity
                }
            }).result.then(function (modalResult) {
                $scope.load();
                $scope.Additionalmethod();
            });
        }
    };
    $scope.delete = function (model) {
        if ($scope.IsShowRequestEditForm) {
            $uibModal.open({
                animation: true,
                templateUrl: '/ng-templates/RequestEdit.html',
                controller: 'RequestEditCtrl',
                size: 'md',
                resolve: {
                    model: { Comment: '' }
                }
            }).result.then(function (modalResult) {

            });
        }
        else {
            if (confirm('آیا از حذف این مورد اطمینان دارید؟')) {
                $http.post('/Additional/DeleteCategoryActivity/' + model.ID).then(function successCallback(res) {
                    if (res.data.success) {
                        $scope.load();
                        $scope.Additionalmethod();
                    } else {
                        notifyShow(res.data.data.error, 0);
                    }
                });
            }
        }
    };
   
});
