Dargah.controller('editMessageCtrl', function ($scope, $http, $uibModal, $uibModalInstance, model, Posts, toaster, PriorityDataSource, MessageTypesDataSource) {
    $scope.isSending = false;
    $scope.model = model;
    $scope.Posts = Posts;
    $scope.PriorityDataSource = PriorityDataSource;
    $scope.MessageTypesDataSource = MessageTypesDataSource;
    $scope.htmlEditorOptions = {
        width: "100%",
        rtlEnabled: true,
        toolbar: {
            items: [
                "undo", "redo", "separator",
                {
                    name: "size",
                    acceptedValues: ["8pt", "10pt", "12pt", "14pt", "18pt", "24pt", "36pt"]
                },
                {
                    name: "font",
                    acceptedValues: ["Arial", "Courier New", "Georgia", "Impact", "Lucida Console", "Tahoma", "Times New Roman", "Verdana", "IRANSans"]
                },
                "separator", "bold", "italic", "strike", "underline", "separator",
                "alignLeft", "alignCenter", "alignRight", "alignJustify", "separator",
                "orderedList", "bulletList", "separator",
                {
                    name: "header",
                    acceptedValues: [false, 1, 2, 3, 4, 5]
                }, "separator",
                "color", "background", "separator",
                "link", "image", "separator",
                "clear", "codeBlock", "blockquote", "separator",
                "insertTable", "deleteTable",
                "insertRowAbove", "insertRowBelow", "deleteRow",
                "insertColumnLeft", "insertColumnRight", "deleteColumn",
                //{
                //    widget: "dxButton",
                //    options: {
                //        text: "Show markup",
                //        stylingMode: "filled",
                //        onClick: function () {
                //            $scope.visiblePopup = true;
                //            $scope.scrollByContentValue = true;
                //            $scope.scrollByThumbValue = true;
                //        }
                //    }
                //}
            ]
        },
        validationStatus: "valid",
        valueType: "html",
        activeStateEnabled: true,
        focusStateEnabled: true,
        placeholder: "اینجا بنویسید ...",
        mediaResizing: {
            enabled: true,
            allowedTargets: ['image']
        },
        bindingOptions: {
            value: "model.EvaluationStandardMinorInformation",
        },
        onValueChanged: function (e) {
            if (e.name === "changedProperty") {
                // handle the property change here
            }
        }
    };


    $scope.selectClosedMessages = function () {
        $uibModal.open({
            animation: true,
            templateUrl: '/templates/selectClosedMessagesModal.html',
            controller: 'SelectClosedMessagesCtrl',
            size: 'lg'
        }).result.then(function (modalResult) {
            $scope.model.RelatedMessageID = modalResult.ID;
            $('input[name="RelatedMessageID"]').val(modalResult.ID);
            $('input[name="RelatedMessageName"]').val(modalResult.Subject);
        });
    };
    $scope.clearSelectClosedMessages = function () {
        $('input[name="RelatedMessageID"]').val('');
        $('input[name="RelatedMessageName"]').val('');
        $scope.model.RelatedMessageID = null;
    };
    $scope.submit = function () {
        if (!$scope.AddMessage.$$element[0].Valid) {
            $scope.disable = false;
            return;
        }
        var rvt = angular.element('input[name="X-CSRF-Token"]').val();
        var httpConfig = { headers: { 'X-XSRF-Token': rvt } };
        var fileData = new FormData();
        fileData.append("ID", $scope.model.ID);
        fileData.append("Subject", $scope.model.Subject);
        for (let file of $('input[name="File"]').map((i, e) => e.value).get()) {
            fileData.append("Files", file);
        }
        fileData.append("Message", $scope.model.Message ? $scope.model.Message : '');
        fileData.append("MessageTypeID", $scope.model.MessageTypeID ? $scope.model.MessageTypeID : '');
        fileData.append("PostRecieverID", $scope.model.PostRecieverID ? $scope.model.PostRecieverID : '');
        fileData.append("PriorityID", $scope.model.PriorityID ? $scope.model.PriorityID : '');
        fileData.append("RelatedMessageID", $scope.model.RelatedMessageID ? $scope.model.RelatedMessageID : '');
        if (typeof $scope.model.Message == 'undefined' || typeof $scope.model.Subject == 'undefined') {
            $scope.isSending = false;
            return false;
        } else {
            $scope.isSending = true;
            $http.post('/additional/PostMessage', fileData, { transformRequest: angular.identity, headers: { 'Content-Type': undefined } }, httpConfig).then(function successCallback(result) {
                if (result.data.success) {
                    toaster.pop('success', "پیام", success);
                    $scope.model.MessageID = result.data.data.MessageID
                    $uibModalInstance.close({ model: $scope.model });
                }
                else {
                    $scope.isSending = false;
                    toaster.pop("error", ErrorMessage, AlertEroorCommand);
                }
            }, function errorCallback(err) {
                $scope.isSending = false;
                alert(err.statusText);
            });
            return false;
        }
    };
    $scope.cancel = function () {
        $uibModalInstance.dismiss('cancel');
    };
});

