Dargah.controller("ProposalModalCtrl", function ($scope, $uibModalInstance, TenderModel, RequestEquipments, ProposalPrice, Tender_Contractor, PacketBox, EquipmentsBox, InfoBox, sumPriceFinall, TenderContractorDiscountAmount, ProposalsSumForeignPrice) {
    $scope.IsRtl = IsRtl
    $scope.TenderModel = TenderModel;
    $scope.RequestEquipments = RequestEquipments;
    $scope.ProposalPrice = ProposalPrice;
    $scope.Tender_Contractor = Tender_Contractor;
    $scope.PacketBox = PacketBox;
    $scope.EquipmentsBox = EquipmentsBox;
    $scope.InfoBox = InfoBox;
    $scope.sumPriceFinall = sumPriceFinall;
    $scope.TenderContractorDiscountAmount = TenderContractorDiscountAmount;
    $scope.proposalsSumForeignPrice = ProposalsSumForeignPrice
    var options = {
        createWords: window.cultureInfo === "fa-IR" ? true : false,
        thousandSeparator: true,
        postfix: '  ',
        allowStartingWithZero: false
    }
    function getThousandGroupName(_igroup) {
        switch (_igroup) {
            case 2: return ' هزار';
            case 3: return ' میلیون';
            case 4: return ' میلیارد';
            case 5: return ' هزار میلیارد';
        }
        return '';
    }
    function digitsToWord3(chars) {
        if (chars == '000') return '';
        var _text = '';
        switch (chars.substring(0, 1)) {
            case '1': _text += 'یکصد'; break;
            case '2': _text += 'دویست'; break;
            case '3': _text += 'سیصد'; break;
            case '4': _text += 'چهارصد'; break;
            case '5': _text += 'پانصد'; break;
            case '6': _text += 'ششصد'; break;
            case '7': _text += 'هفتصد'; break;
            case '8': _text += 'هشتصد'; break;
            case '9': _text += 'نهصد'; break;
        }
        if (_text.length > 0) _text += ' و ';
        if (chars.substring(1, 2) == '1') {
            switch (chars.substring(2, 3)) {
                case '0': _text += 'ده'; break;
                case '1': _text += 'یازده'; break;
                case '2': _text += 'دوازده'; break;
                case '3': _text += 'سیزده'; break;
                case '4': _text += 'چهارده'; break;
                case '5': _text += 'پانزده'; break;
                case '6': _text += 'شانزده'; break;
                case '7': _text += 'هفده'; break;
                case '8': _text += 'هیجده'; break;
                case '9': _text += 'نوزده'; break;
            }
        }
        else {
            switch (chars.substring(1, 2)) {
                case '0': _text = _text.substring(0, _text.length - 3); break;
                case '2': _text += 'بیست'; break;
                case '3': _text += 'سی'; break;
                case '4': _text += 'چهل'; break;
                case '5': _text += 'پنجاه'; break;
                case '6': _text += 'شصت'; break;
                case '7': _text += 'هفتاد'; break;
                case '8': _text += 'هشتاد'; break;
                case '9': _text += 'نود'; break;
            }
            if (_text.length > 0) _text += ' و ';
            switch (chars.substring(2, 3)) {
                case '0': _text = _text.substring(0, _text.length - 3); break;
                case '1': _text += 'یک'; break;
                case '2': _text += 'دو'; break;
                case '3': _text += 'سه'; break;
                case '4': _text += 'چهار'; break;
                case '5': _text += 'پنج'; break;
                case '6': _text += 'شش'; break;
                case '7': _text += 'هفت'; break;
                case '8': _text += 'هشت'; break;
                case '9': _text += 'نه'; break;
            }
        }
        return _text;
    }
    function digitsToWord(chars, options) {
        if (chars.includes('chl') || chars.length == 0) return 'در انتظار ورود اعداد';
        var _lengthMod3 = chars.length % 3;
        if (_lengthMod3 > 0) for (i = 0; i < 3 - _lengthMod3; i++) chars = '0' + chars;
        if (chars == '000') return 'صفر' + options.postfix;
        var _groups_count = chars.length / 3;
        var _groups = new Array();
        var _text = '';
        for (i = 0; i < _groups_count; i++) {
            _groups[i] = chars.substring(i * 3, i * 3 + 3);
            if (_groups[i] == '000') continue;
            if (_text.length > 0) _text += ' و ';
            _text += $.digitbox.digitsToWord3(_groups[i]);
            _text += $.digitbox.getThousandGroupName(_groups_count - i);
        }
        return _text + options.postfix;
    }
    function isNullOrUndefined(model) {
        if (typeof model == "number") {
            return model + "";
        }
        if (model == null || model == undefined) {
            return "";
        }
        if (typeof model == "string") {
            model = model.search(",") == -1 ? model : model.replaceAll(/,/g, '')
            return model;
        }
    }
    Tender_Contractor.PrepaymentPriceLetter = digitsToWord(isNullOrUndefined(Tender_Contractor.PrepaymentPrice), options);
    Tender_Contractor.ForeignProposalPriceLetter = digitsToWord(isNullOrUndefined(Tender_Contractor.ForeignProposalPrice), options);

    $scope.proposalsSumForeignPriceLetter = digitsToWord(isNullOrUndefined($scope.proposalsSumForeignPrice), options);

    $scope.ProposalPriceLetter = digitsToWord(isNullOrUndefined($scope.ProposalPrice), options);
    $scope.sumPriceFinallLetter = digitsToWord(isNullOrUndefined($scope.sumPriceFinall), options);
    $scope.Tender_Contractor.CarriagePriceLetter = digitsToWord(isNullOrUndefined($scope.Tender_Contractor.CarriagePrice), options);
    $scope.Tender_Contractor.DiscountRateLetter = digitsToWord(isNullOrUndefined($scope.Tender_Contractor.DiscountRate), options);
    $scope.Tender_Contractor.SparePartsPriceLetter = digitsToWord(isNullOrUndefined($scope.Tender_Contractor.SparePartsPrice), options);
    $scope.Tender_Contractor.OtherPriceLetter = digitsToWord(isNullOrUndefined($scope.Tender_Contractor.OtherPrice), options);
    $scope.Tender_Contractor.ProposalOfferPercentLetter = digitsToWord(isNullOrUndefined($scope.Tender_Contractor.ProposalOfferPercent), options);
    $scope.Tender_Contractor.ProposalTaxPriceLetter = digitsToWord(isNullOrUndefined($scope.Tender_Contractor.ProposalTaxPrice), options);
    $scope.Tender_Contractor.ProposalPriceWithoutDiscountLetter = digitsToWord(isNullOrUndefined($scope.Tender_Contractor.ProposalPriceWithoutDiscount), options);
    $scope.Tender_Contractor.PackagePriceLetter = digitsToWord(isNullOrUndefined($scope.Tender_Contractor.PackagePrice), options);
    $scope.TenderContractorDiscountAmountLetter = digitsToWord(isNullOrUndefined($scope.TenderContractorDiscountAmount), options);
    $scope.proposalsSumPriceLetter = digitsToWord(isNullOrUndefined($scope.proposalsSumPrice), options);
    $scope.submit = function () {
        $scope.ProposalPrice = parseInt(String($scope.ProposalPrice).split(',').join(''));
        $uibModalInstance.close({
            ProposalPrice: $scope.ProposalPrice, ForeignProposalPrice: $scope.ForeignProposalPrice, RequestEquipments: $scope.RequestEquipments
        });
    };
    $scope.cancel = function () {
        $uibModalInstance.dismiss('cancel');
    };
});
