Dargah.controller('AuthorizeDigitalSignatureAndCertificate', function ($scope, $state, $interval) {
    $scope.IsRtl = IsRtl;
    $scope.Model = Model;

    if ($scope.Model.allDone) {
        setTimeout(() => {  $state.go('Portal', {}, {reload:true}); }, 10000);
    }

    $scope.Model.isSendingForAuthentication = false;
    $scope.Model.ExpDate = '';
    $scope.submit = async function (e) {
        
        if (!$scope.myForm.$$element[0].Valid) {
            return false;
        };
        $scope.Model.isSendingForAuthentication = true;

        let res = await fetchPost("/profile/digitalsignature", $scope.Model);
        
        if (res.success) {
            $scope.Model = res.data;
            
            if ($scope.Model.HasError == true) {
                
                $scope.$apply();
                return false;
            }
        }
        $scope.$apply();
        
        if ($scope.Model.AuthRedirect != null && $scope.Model.AuthRedirect.length != 0) {
            
            window.location = $scope.Model.AuthRedirect;
            return true;
        }

        /*setTimeout(() => {  $state.go('Portal', {}, { reload: true }); }, 10000);*/
        return false;
    };

    $scope.resendOTP = async function (e) {
        
        let res = await fetch("/profile/ResendDigitalSignatureAuthOTP");

        $scope.SendOtp();
    }
    //// ---- >>>> OTP and counter
    $scope.CountDown = {
        getTimeRemaining: function (endtime) {
            var t = Date.parse(endtime) - Date.parse(new Date());
            var seconds = Math.floor((t / 1000) % 60);
            var minutes = Math.floor((t / 1000 / 60) % 60);
            var hours = Math.floor((t / (1000 * 60 * 60)) % 24);
            var days = Math.floor(t / (1000 * 60 * 60 * 24));
            return {
                'total': t,
                'days': days,
                'hours': hours,
                'minutes': minutes,
                'seconds': seconds
            };
        },
        initializeClock: function (endtime) {
            function updateClock() {
                var t = $scope.CountDown.getTimeRemaining(endtime);
                $scope.CountDown.days = t.days;
                $scope.CountDown.hours = ('0' + t.hours).slice(-2);
                $scope.CountDown.minutes = ('0' + t.minutes).slice(-2);
                $scope.CountDown.seconds = ('0' + t.seconds).slice(-2);
                $scope.ExpDate = $scope.CountDown.minutes + ':' + $scope.CountDown.seconds;
                if (t.total <= 0) {
                    $interval.cancel(timeinterval);
                }
            }
            updateClock();
            var timeinterval = $interval(updateClock, 1000);
        }
    }

    $scope.ExpDate = '';
    $scope.SendOtp = async function () {
        
        var deadline = new Date(Date.parse(new Date()) + 2 * 60 * 1000);
        $scope.CountDown.initializeClock(deadline);
    }
    $scope.SendOtp();
    $scope.revokeCertificateRequest = async function (OnlyRemoveAuth) {
        let response = await fetchPost(`/Profile/revokeCertificateRequest?onlyremoveauth=${OnlyRemoveAuth}`);
        if (response.success) {
            if (OnlyRemoveAuth) {
                notifyShow(response.data, 3);
                $state.go('DigitalSignature', {}, { reload: true })
            }
        }
        else {
            notifyShow(response.data, 3);
        }
    }
});
