'use strict';

(function () {
    // persianDateConverter class
    window.persianDateConverter = (function () {
        var grgSumOfDays = Array(Array(0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334, 365), Array(0, 31, 60, 91, 121, 152, 182, 213, 244, 274, 305, 335, 366));
        var hshSumOfDays = Array(Array(0, 31, 62, 93, 124, 155, 186, 216, 246, 276, 306, 336, 365), Array(0, 31, 62, 93, 124, 155, 186, 216, 246, 276, 306, 336, 366));
        function toPersianDate(grgYear, grgMonth, grgDay, formatLong) {
            var hshYear = grgYear - 621;
            var hshMonth, hshDay;

            var grgLeap = grgIsLeap(grgYear);
            var hshLeap = hshIsLeap(hshYear - 1);

            var hshElapsed;
            var grgElapsed = grgSumOfDays[(grgLeap ? 1 : 0)][grgMonth - 1] + grgDay;

            var XmasToNorooz = (hshLeap && grgLeap) ? 80 : 79;

            if (grgElapsed <= XmasToNorooz) {
                hshElapsed = grgElapsed + 286;
                hshYear--;
                if (hshLeap && !grgLeap)
                    hshElapsed++;
            }
            else {
                hshElapsed = grgElapsed - XmasToNorooz;
                hshLeap = hshIsLeap(hshYear);
            }

            for (var i = 1; i <= 12; i++) {
                if (hshSumOfDays[(hshLeap ? 1 : 0)][i] >= hshElapsed) {
                    hshMonth = i;
                    hshDay = hshElapsed - hshSumOfDays[(hshLeap ? 1 : 0)][i - 1];
                    break;
                }
            }

            if (formatLong)
                return hshDayName(hshDayOfWeek(hshYear, hshMonth, hshDay)) + "  " + hshDay + " " + calNames("hf", hshMonth - 1) + " " + hshYear;
            else
                return hshYear + "/" + hshMonth + "/" + hshDay;
        }

        function toGregorianDate(hshYear, hshMonth, hshDay) {
            var grgYear = hshYear + 621;
            var grgMonth, grgDay;

            var hshLeap = hshIsLeap(hshYear);
            var grgLeap = grgIsLeap(grgYear);

            var hshElapsed = hshSumOfDays[hshLeap ? 1 : 0][hshMonth - 1] + hshDay;
            var grgElapsed;

            if (hshMonth > 10 || (hshMonth == 10 && hshElapsed > 286 + (grgLeap ? 1 : 0))) {
                grgElapsed = hshElapsed - (286 + (grgLeap ? 1 : 0));
                grgLeap = grgIsLeap(++grgYear);
            }
            else {
                hshLeap = hshIsLeap(hshYear - 1);
                grgElapsed = hshElapsed + 79 + (hshLeap ? 1 : 0) - (grgIsLeap(grgYear - 1) ? 1 : 0);
            }

            for (var i = 1; i <= 12; i++) {
                if (grgSumOfDays[grgLeap ? 1 : 0][i] >= grgElapsed) {
                    grgMonth = i;
                    grgDay = grgElapsed - grgSumOfDays[grgLeap ? 1 : 0][i - 1];
                    break;
                }
            }

            return grgYear + "-" + grgMonth + "-" + grgDay;
        }

        function grgIsLeap(Year) {
            return ((Year % 4) == 0 && ((Year % 100) != 0 || (Year % 400) == 0));
        }

        function hshIsLeap(Year) {
            Year = (Year - 474) % 128;
            Year = ((Year >= 30) ? 0 : 29) + Year;
            Year = Year - Math.floor(Year / 33) - 1;
            return ((Year % 4) == 0);
        }

        function hshDayOfWeek(hshYear, hshMonth, hshDay) {
            var value;
            value = hshYear - 1376 + hshSumOfDays[0][hshMonth - 1] + hshDay - 1;

            for (var i = 1380; i < hshYear; i++)
                if (hshIsLeap(i)) value++;
            for (var i = hshYear; i < 1380; i++)
                if (hshIsLeap(i)) value--;

            value = value % 7;
            if (value < 0) value = value + 7;

            return (value);
        }

        function hshDayName(DayOfWeek) {
            return calNames("df", DayOfWeek % 7);
        }

        function calNames(calendarName, monthNo) {
            switch (calendarName) {
                case "hf": return Array("فروردين", "ارديبهشت", "خرداد", "تير", "مرداد", "شهريور", "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند")[monthNo];
                case "ge": return Array(" January ", " February ", " March ", " April ", " May ", " June ", " July ", " August ", " September ", " October ", " November ", " December ")[monthNo];
                case "gf": return Array("ژانویه", "فوریه", "مارس", "آوریل", "مه", "ژوثن", "ژوییه", "اوت", "سپتامبر", "اكتبر", "نوامبر", "دسامبر")[monthNo];
                case "df": return Array("شنبه", "یک‌شنبه", "دوشنبه", "سه‌شنبه", "چهارشنبه", "پنج‌شنبه", "جمعه")[monthNo];
                case "de": return Array("Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday")[monthNo];
            }
        }

        return {
            toPersian: function (value, formatLong) {
                var valueSplit = String(value).split('/');
                var year = parseInt(valueSplit[0]),
                    month = parseInt(valueSplit[1]),
                    day = parseInt(valueSplit[2]);
                return toPersianDate(year, month, day, formatLong);
            },
            toGregorian: function (value) {
                var valueSplit = String(value).split('/');
                var year = parseInt(valueSplit[0]),
                    month = parseInt(valueSplit[1]),
                    day = parseInt(valueSplit[2]);
                return toGregorianDate(year, month, day);
            }
        };
    })();


    // persian number class
    window.persianNumberConverter = (function () {
        var toDigit = function (value) {
            return String(value).replace(/\d+/g, function (digit) {
                var enDigitArr = [], peDigitArr = [];
                for (var i = 0; i < digit.length; i++) {
                    enDigitArr.push(digit.charCodeAt(i));
                }
                for (var j = 0; j < enDigitArr.length; j++) {
                    peDigitArr.push(String.fromCharCode(enDigitArr[j] + 1728));
                }
                return peDigitArr.join('');
            });
        };
        return {
            toDigit: toDigit
        };
    })();

    // persian class
    window.persian = (function () {
        return {
            toDigit: function (value) {
                return persianNumberConverter.toDigit(value);
            },
            toMoney: function (value, ispersian = true) {
                value = String(value).replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                return ispersian ? persianNumberConverter.toDigit(value) : value;
            },
            toDate: function (value, formatLong) {
                return persianDateConverter.toPersian(value, formatLong);
            },
            toDate2: function (value, formatLong) {
                // 2016-01-10T05:20:58.227
                value = value.toISOString();
                value = String(value).substring(0, String(value).indexOf('T')).replace('-', '/').replace('-', '/');
                return persianDateConverter.toPersian(value, formatLong);
            },
            toGregorianDate: function (value) {
                return persianDateConverter.toGregorian(value)
            },
            changeKeyboard: function (value) {
                if (!value) return;

                var persianChar = ["ض", "ص", "ث", "ق", "ف", "غ", "ع", "ه", "خ", "ح", "ج", "چ", "ش", "س", "ی", "ب", "ل", "ا", "ت", "ن", "م", "ک", "گ", "ظ", "ط", "ز", "ر", "ذ", "د", "پ", "و", "؟"],
                    englishChar = ["q", "w", "e", "r", "t", "y", "u", "i", "o", "p", "[", "]", "a", "s", "d", "f", "g", "h", "j", "k", "l", ";", "'", "z", "x", "c", "v", "b", "n", "m", ",", "?"];

                for (var i = 0, charsLen = persianChar.length; i < charsLen; i++) {
                    value = value.replace(new RegExp(persianChar[i], "g"), englishChar[i]);
                }
                for (var i = 0; i < englishChar.length; i++) {
                    value = value.replace(new RegExp(englishChar[i], "g"), persianChar[i]);
                }
                console.log(value);
                return value;
            }
        }
    })();
})();

// jquery componet for persian input
(function ($) {
    $.fn.persianInput = function () {
        return this.each(function () {
            var _input = $(this);
            _input.bind('keydown', function (e) {
                e.key = persianNumberConverter.toDigit(e.key);
                //_input.val(persianNumberConverter.toDigit(_input.val()));
                //console.log(e);
            });
            _input.val(persianNumberConverter.toDigit(_input.val()));
        });
    };
})(jQuery);

